window.POEM_DB=window.POEM_DB||{};POEM_DB["qing_022"]={"n":"毛奇龄","dyn":"清","poems":[{"t":"读史诗","f":"古风","c":["张生本文孺，夜起受简编。","忽从游侠行，破产思报韩。","志意久不达，?郁何由宣。","一朝风云生，帷幄进谠言。","持筹并握箸，所至无拘挻。","当其家居时，游戏商洛间。","平交结耆旧，伟制裁衣冠。","辟谷散暮气，斸芝当晨餐。","贫贱可肆志，富贵难久安。","宁负平勃交，勿弃园绮欢。","遐哉亦松游，岂为求神仙。","兰成烟霞姿，倜傥超等伦。","少小作钞撰，落笔如散银。","并使嚼鹦鹉，同等摩麒麟。","池台绍河曲，钟鼓宴洛滨。","太平三十载，总是梁朝人。","岂知苍鹅飞，顿令玉马湮。","朱桁撤单舶，青袍蔽长津。","庶望下亭旅，重遘南郡春。","如何走秦关，别馆留孤臣。","三户既已尽，七叶谁见亲。","从此东海鸟，长作西都宾，阳春方递代，去故当就新。","寒暑有时尽，日月无返晨。","临都哭三昼，绕屋步百巡。","岂不被显爵，亦既叨殊恩。","无如慕乡井，惠好难重陈。","生逢乱离世，老作异代身。","江南草长时，回望情弥殷。","枳橘岂秦产，夷齐本商民。","一吟思归辞，泪下沾衣巾。"]},{"t":"重经上江过小孤山望高良作","f":"五言古诗","c":["晨飔解流潮，朝暾坼遐沚。","中流辨孤屿，相越尚百里。","流峭去榜逆，帆迫来洲驶。","忽泊斗岩下，遂至洪泽里。","三江憺前期，九派殊昔理。","瞩异物不延，时迁景为徙。","涤水掬流清，搴花摘叶委。","羁孤泛无常，流浪讵有已。","宁当越前峰，去逐高良子。"]},{"t":"奉召赴都经泰岳遥望有作 其一","f":"五言古诗","c":["朝日泛旸谷，孤光动天门。","鸿濛启青苍，仰见乔岳尊。","郁若灏气接，下与浮云骞。","群峰争嵯峨，拱列同星垣。","我欲凌绝巘，俯视周大寰。","奋迅鲜羽翼，屼峍难攀援。","从来圣神出，升陟柴以燔。","五王觐国后，三观窥河源。","今适遘王会，将策明堂文。","下诏召博士，因之及公孙。","自笑圭筚士，敢为封禅言。","神功发眺听，博议开浑元。","但当入林丘，挥手长松间。"]},{"t":"奉召赴都经泰岳遥望有作 其二","f":"五言古诗","c":["夙昔爱天孙，层霄踊双足。","俯仰志不遂，高卧沧海曲。","结念周八荒，扶舆久脱辐。","垂老始被徵，一憩梁父麓。","崇岩倚重云，白日系匡谷。","欲吸沆瀣浆，蹙额惭满腹。","我有鸡斯乘，蹑峤如驾陆。","入林招洪崖，望海诮徐福。","折取东峰枝，间与夸父逐。","历险理自明，升远象以瞩。","何为盼修途，展转愧寥廓。"]},{"t":"送李检讨予养还山 其一","f":"五言古诗","c":["招弓下中山，葺屦朝上京。","公车何崔嵬，所藉高世名。","志气本超卓，文藻亦纵横。","谁言紫阁翁，少小无宦情。","至尊重良会，召见开延英。","食以朱贝柈，沃以碧笋羹。","给札令呈艺，轹落无弱营。","因之授册府，入署承明庭。","夏云方南驰，夜火将西倾。","一旦上省养，孝感动圣明。","衔轼谢京邑，衣锦投乡程。","祖帐各掔袂，反若千里行。","人生有初服，亦欲奠所贞。","何为坐拘牵，閟志徒怦怦。"]},{"t":"送李检讨予养还山 其二","f":"五言古诗","c":["圜凿不受枘，樛枝岂为辐。","况有终南行，白华蔓空谷。","曾参著儿冠，虞氏就养屋。","渴借桑门瓜，甘怀洞庭橘。","昔有棒檄生，色喜逮亲育。","今我亦何为，但指风与木。","蓬池畜嘉鱼，得为亲釜熟。","迎养曷不可，遽尔返邦族。","白衣虽改绣，披之当莱服。","碧山张学士，当此悔解幞。","天凉卖浆稀，官邸日不足。","临朝思贻鞭，无马堪竞逐。","但咏《南陔》诗，双泪下簌簌。"]},{"t":"送李检讨予养还山 其三","f":"五言古诗","c":["太华有佳气，乃在龙门山。","千载启石室，一若通武关。","盘冈与绣岭，隐者藏其间。","况复踵灵异，于此产马班。","当今居史宬，畴职笔与删。","翳众多匠手，而予犹汗颜。","维彼粲门子，高踞兰台端。","慷慨忽弃置，踯躅谁跻攀。","柱下去一宿，撰事留五难。","有论责韩愈，无书报任安。","新秋坐林薄，仰看飞云还。","窗通紫微远，户傍太乙寒。","日月过櫩隙，晨夕躬庭餐。","视此三寸扰，何如一日闲。","予有湖上业，滟潋通周官。","思以割一曲，未敢徼圣欢。","横门出祖道，藉藉皆来观。","缅彼前史贤，相顾增长叹。"]},{"t":"打虎儿行","f":"古风","c":["打虎儿，乃在汴梁之禹州，禹州城外朱家楼。","小儿十一随父耕，深林有虎斑毛成。","飗飗黑风吹草根，乘风攫人谁敢撄？","小儿不识虎，疑是狐与狸。","陡然见虎衔父肢，咆哮草际风来吹。","儿啼向风不得父，把杙打虎截虎路。","三尺童子五尺杙，凭空击去著虎臆。","虎惊顾儿舍父逸，深林风草皆无色。","禹州太守呼小儿，予之以帛饱以糜。","予时在署识儿面，披发跳掷真儿嬉。","问儿打虎虎何似，举手张牙作虎势。","假虎隐幔恐小儿，小儿惊避力不支。","当时见虎得无怖，此事我亦昧其故。","禹州太守省得知，是时小儿知有父。","男儿七尺纵复横，争名攫利万里行。","高堂存没总不问，那肯舍命恋所生？","我所思，打虎儿。"]},{"t":"陈州村人或赋上阳白发人者毛甡过闻而感焉","f":"七言古诗","c":["河南河北不种麻，上阳宫中无好花。","玉沟流水载花出，从此宫墙不能八。","宛丘东路桑落村，漂流近在村东园。","黄门持鹞晚归寂，公主望乡朝负暄。","西山盗贼走春电。","花落重飞旧巢燕。","舞鹭翻垂篽宿衣，沤麻添作西宫线。","金舆入蜀未得归，道傍不用伤蛾眉。","《上阳白发》谁家赋，能使傍人双泪垂。"]},{"t":"登白鹭洲值施使君留萧江有怀","f":"七言古诗","c":["石阳城边白鹭洲，萋萋碧草环洲流。","层楼百尺俯寒潦，有客独登楼上愁。","楼前寂历众山暮，万里江流自来去。","天半横吹赣浦帆，云中恍辨虔阳树。","我来眺望九日余，芳洲犹采红茱萸。","遥山不断故乡雁，沿流时羡清江鱼。","故人乘兴久舒啸，千载南楼鲜同调。","看月宁分佐史床，临风空著参军帽。","相思渺渺萦素波，秋花开映波中螺。","凭栏欲作《登楼赋》，不见夫君奈若何。"]},{"t":"姜尧招登香炉峰绝顶同姜十七廷梧商二徵说","f":"七言古诗","c":["秋山崒嵂海日红，浮晖倒映金芙蓉。","苍崖负杖招羽客，携我直上香炉峰。","枫林黄叶下幽壑，杖底风吹草衣薄。","石屋高看洞鸟翻，横梁斜度山花落。","秋空望海海色飞，赤城万里烟霏霏。","越王台上青烽起，夏后祠前白雁稀。","玉函金简探难得，况蹈岖嵚未曾息。","北谷空标承露台，南还竟负凌风翼。","苍崖四顾意气开，吹笙跨鹤真仙才。","何年乞汝盈箱药，共俟安期海上来。"]},{"t":"同王徵士听杨太常弹琴篇","f":"古风","c":["成连入海不复返，人间尚有雍门周。","呼天抢地抱焦木，一鼓再弹双泪流。","晋侯清徵召祲禬，杨氏宫亡失行在。","五音升降得丧殊，何事民流角声败。","萧郎左卫本戎伍，能定明堂五行舞。","谁怜故器抱殷遗，遽使新声写淇浦。","开元供奉烧尾琴，上皇赐比双南琛。","梨园既散海青死，但留箧底空沈吟。","当年大合驾象辂，尚对皇娥鼓瑶素。","鼎湖龙去竟不还，自抱乌号哭晨昏暮。","毛甡家畜潞国弦，诸王颁在崇祯年。","欲遗太常共搏拊，天涯修阻思茫然。","从今《大雅》日淫漫，莫遣风流使中断。","他日相逢袁孝尼，愿得先传《广陵散》。"]},{"t":"柳花歌寓芜城作","f":"七言古诗","c":["春风濯濯江南路，吹过邗关到瓜步。","邗关三月春草长，市楼大道怨春阳。","阳春初开日杲杲，大道花飞一何早。","清明渐近细雨来，绕树游丝堕缥缈。","游丝缥缈绕如雾，绾入隋堤柳条住。","隋堤柳色青珑璁，娓娓流莺啼不去。","流莺啼处停玉镳，依依拂面尽长条。","挥鞭既度红栏曲，驱车还上绿杨桥。","红栏绿柳心断绝，隋苑隋堤有离别。","新声三叠何处吟，弱线千条倩谁折。","可怜草青及春暮，可怜绿柳低还仆。","青楼曳翠萦酒垆，白马连钱系归渡。","低枝毵毵接长坂，高枝蓬蓬白花满。","茫茫飞雪绕去迟，冉冉轻绵罥来晚。","翩随晚蝶罥朱花，缓向春烟拂玉鸦。","几时飘飖落西苑，几时流荡去南家。","南家西苑两相叶，流荡飘飖日憔悴。","春风吹去不上天，春燕衔将复垂地。","初翻积雨障轻尘，更度妆楼袅素茵。","满眼离披不知处，愁杀东西行路人。"]},{"t":"宣德窑青花脂粉箱为莱阳姜仲子赋","f":"古风","c":["君不见宣皇宫中脂粉箱，青花素瓷出上方。","陶模范埴好形像，烧胚膊非寻常。","曼身穴腹判两截，一道坎中周四旁。","融脂沦粉恐胶结，洄漩复壁流温汤。","宛若丽华斗妆罢，宫沟浅腻萦苑墙。","何年此物坐弃掷，竟置姜郎砚塘侧。","隔盎微闻金粉香，开奁尚带胭脂色。","摩挲日剧但把弄，未审甄人定何用。","贾胡欲认不辨名，卢女相看宛如梦。","连昌宫监老不堪，落花时节来江南。","见此忽尔惊叹息，云是先朝旧承值。","曾赐昭阳系臂红，玉函脂粉在其中。","盘间花贮甘泉露，镜里衣穿仁寿铜。","良人少使望春树，百子池前早祠去。","额画销朱点晕重，指尖碾玉当窝处。","由来摘揥最烦纡，惟此当窗好匀注。","紫水开唇恍泻丹，红绵扑粉如飞絮。","因之瓦甒独见亲，珠椷宝柙皆非伦。","履箱银钥擎奴子，钿合金钗付贵嫔。","谁知世事颇难测，金狄铜仙雨中拆。","拾得皇孙绣褓钱，抛来魏后湘纹尺。","昭华翠琯摧井干，道傍团扇遮弥寒。","库名宜圣总散失，独留金碗传人间。","承恩当日授佳器，前后纷纶尚能纪。","花箱虽好何代贻，知为宜德年间事。","我来吴会当岁除，东湖水落西流鱼。","姜郎酒后出示我，令我抱之长欷歔。","黄钟土釜本反覆，几见桑田变成谷。","半世红颜委道途，上阳白发谁膏沐。","箱空脂尽粉未调，当前若个真娥媌。","君家陈宝世无算，为汝一歌宣德窑。"]},{"t":"诏观西洋国所进狮子因获遍阅虎圈诸兽敬制长句纪事和高阳相公","f":"古风","c":["古皇慎德开四译，内被绥侯外蛮貊。","贡物区为王会文，共球载在宾庭册。","河镠畎翟献上方，兜离僸?陈明堂。","三灵既应百神洽，般般之兽皆翱翔。","康熙戊午十七载，神武声名播遥海。","五畤从教白泽来，千门真见黄龙采。","鸦翎习习负矢飞，鸡斯乘之归林支。","诸方执贽俨相列，东渐溟渤流沙西。","于中有国名古里，曾渡澜沧作海市。","鱼眼看波射水红，鲛丝织浪翻云紫。","地当申未产兽雄，金精杰出毛群中。","衔绦饰组献天子，裁贝作章辞礼恭。","从容槛致射熊馆，不为珍禽为怀远。","虎落时看接上林，鹰房秋到移南苑。","廷臣侍从欲赋诗，皇恩有诏徐观之。","圆目昂鼻有筋力，悬星掣电无雄雌。","独怜耏发未卷曲，曳尾绁绁若散丝。","衣被欲成鞠色见，牙龈不使钩形施。","尔时群槛柙诸兽，木垒枪樊列前囿。","熊罴避路不用当，虎豹攀栏有时吼。","青鸾赤雀相对栖，豪猪野马争游嬉。","张昭见此不动色，朱亥在傍何所思。","闻之有熊狩旸谷，获得狻猊比牛畜。","汉时安息亦献斯，形似麒麟但无角。","从兹郊祀播乐章，射乌格鹿非寻常。","铙吹已陈《朱鹭曲》，徵歌还及白狼王。","何如储偫未完缉，诏遣求贤共来集。","东堂甫布网罗成，西域刚逢旅獒入。","招摇乍启禁篽开，白麟有对皆奇才。","请看太保《卷阿》赋，恍见文王灵囿来。"]},{"t":"武进恽仲升过话","f":"五言律诗","c":["熟食春前近，扁舟江上来。","乌啼木客冢，雨过越王台。","畏路行何虑，空樽语易哀。","函关天堑杳，使汝恋蒿莱。"]},{"t":"蔡五十一同伯兄过寻甡西湖","f":"五言律诗","c":["故国归难得，春山望欲穷。","呼人谷鸟下，寻弟黍苗中。","零雨淹湖寺，浮云蔽海东。","三年襟上血，相视暮镫红。"]},{"t":"赴新安至七里滩作","f":"五言律诗","c":["东关苦行迈，南涉上新安。","水木千云乱，沙禽拂浪寒。","孤吟随荡桨，多难负垂竿。","何日风波静，还来住此滩。"]},{"t":"泊严滩有感","f":"五言律诗","c":["晚泊傍斜晖，临江泪滴衣。","年华新岁改，京国故人稀。","云散岗峦彩，天垂薜荔围。","严陵台下水，但见暮潮归。"]},{"t":"孝女","f":"五言律诗","c":["孝女秉幽姿，灵帏展素丝。","春兰时会鼓，夜火满丛祠。","江畔青螺水，碑阴黄绢词。","商船留赛去，愁煞上潮时。"]},{"t":"经张稊旧居 其一","f":"五言律诗","c":["尚有青堂赠，宁知白马来。","盘飧仍地主，涕泪满泉台。","丛草留人暗，繁星照户开。","邻家吹笛苦，中夜起悲哀。"]},{"t":"经张稊旧居 其二","f":"五言律诗","c":["十载穷泉路，千秋处士庐。","骄儿彭泽训，难弟晋阳书。","棘楚悲黄鸟，乡潭上白鱼。","谁怜徐氏剑，犹挂子云居。"]},{"t":"经张稊旧居 其三","f":"五言律诗","c":["不作西州哭，依然东道亲。","文章真坠地，朋旧尚为人。","海鹤何年返，山花几度春。","空堂樽酒夜，独坐听鸡晨。"]},{"t":"清流关谒关将军祠","f":"五言律诗","c":["夫子汾川秀，风流世所师。","关山萦峻岭，镫火照神祠。","集木鸦飞后，垂堂虎卧时。","同为亡命客，下马一相思。"]},{"t":"予宿桐音宅出所赋慰诗四章妙丽愀怆讽之伤怀因勉酬三诗导情 其一","f":"五言律诗","c":["故国藏车日，他乡卖饼人。","秋衣怜季布，夜酒对孙宾。","阁下红蕉暗，镫前白发新。","十年悲往事，相顾泪盈巾。"]},{"t":"予宿桐音宅出所赋慰诗四章妙丽愀怆讽之伤怀因勉酬三诗导情 其二","f":"五言律诗","c":["依徒当时暮，还归未画游。","久辞荀里去，仍向孔门投。","霜叶吟东郭，秋星坠北楼。","谁怜频把袂，犹揽旧乌裘。"]},{"t":"予宿桐音宅出所赋慰诗四章妙丽愀怆讽之伤怀因勉酬三诗导情 其三","f":"五言律诗","c":["困日知音少，衰年好会难。","惊心听漏促，久语落杯寒。","妙句当筵发，娇儿出幔看。","夜阑生感激，对饭不能餐。"]},{"t":"谒嵩岳","f":"五言古诗","c":["太室开天表，崇丘奠土中。","主名高四域，受秩比三公。","日月环区宅，阴阳割浑濛。","歌崧扬峻极，望祀礼昭融。","华盖标方顶，金壶启上宫。","翕河承汉禅，卜洛载周工。","别观翔修鹤，层城倚大熊。","藏书凭玉女，过涧遇青童。","洞闭能围雪，梯长恍御风。","群山咸拱岳，万岁自呼嵩。","槐弟封尧爵，菖羊采少翁。","浮丘闲驾羽，子晋妙吹筒。","石酒龙精白，岩花凤首红。","烟霏春渺渺，水滴午漴漴。","虚壑涵深矿，空梁拔断虹。","天关应再辟，帝座俨相通。","险塞分河内，灵祇屈岱东。","神京怀旧服，终古赖攸同。"]},{"t":"行次左蠡放船出南康已来舟中寄蔡五十一仲光姜十七廷梧张五杉并呈施湖西赵司马骆崇仁何奉新诸公","f":"五言古诗","c":["流浪还齐地，苍茫向楚隅。","何时经夏口，此去是洪都。","乡信淹江雁，生涯寄水凫。","仲宣思故国，阮氏泣穷途。","早岁栖中露，频年诎负涂。","书曾降故将，行独后诸儒。","才浅人争忌，赀贫志亦愚。","山萁书有罪，梁燕语当诛。","张俭将归塞，童鸿反去吴。","相君真解绶，浣女果捐躯。","走险胡全跋，昂霄尾毕逋。","有家怜季布，易氏识陶朱。","宴序倾金涧，诗成博锦褕。","宅犹留鲍照，婿欲赘淳于。","北顾空骐骥，南行觅湛卢。","浮名偕草木，放迹在菰芦。","彭泽宵经县，鄱阳晓渡湖。","清秋凉袭袂，白日醉提壶。","避地依五老，环波洗二孤。","篮舆邀栗里，宫锦谢当途。","每念同袍士，还思旧酒徒。","探书登夏穴，修禊绕春芜。","不见三秋艾，相思两地荂。","风舷时转侧，霜柳暗凋枯。","虚羡云间鹤，恒随樯上乌。","怀人难命驾，无道但乘桴。","绿水愁徒涉，青天想共呼。","高峰追白社，寒浦泣苍梧。","妄踞洪崖室，还寻卓氏垆。","无端依水马，何处忆莼鲈。","去国曾捐冕，通关不弃繻。","归装输陆贾，游仕愧秋胡。","最恨生多劣，仍怜世善诬。","凉才宜刖石，暗地岂投珠。","嫉翠连残羽，摧翘及弃樗。","狂书焚《蒯子》，遗论毁《潜夫》。","分鲜金箱秘，情甘溷厕污。","张苍三历尽，司马一书无。","贸贸忘荣落，悠悠度晓晡。","拂龟亡决策，借箸昧前图。","愁听歌商女，惊看秀木奴。","荒城频鼓角，末技厌吹竽。","抱璞思俱寂，书空手自摸。","羁栖同燕雀，辗转似蜘蛛。","海阔从浮泊，天高趁远徂。","留情追沅沣，投老近番禺。","市舶咨梁贾，仙山访藐姑。","遄车需载辅，相瞽赖匡扶。","犹幸逢知己，先经宦此区。","剸鱼跳幸舍，漉酒滥军厨。","兔苑尝裁赋，龙门愿棒枢。","芜文烦啧啧，汎爱首区区。","南野应过眼，章流久浃肤。","固将凭永久，且复倚斯须。","飘荡回蓬荻，遭逢任辘轳。","时方捐苎葛，节又采茱萸。","率旷知依栈，穿林念守株。","草留寒蝶栩，波逐细鱼濡，多泪啼猿狖，难行唤鹧鸪。","孤怀谁告语，长望起踌躇。"]},{"t":"驾幸温泉恭赋","f":"五言古诗","c":["羽肃句陈外，波开帐殿中。","咸池长浴日，华渚自流虹。","晓度榆关远，春从黍谷通。","慈宁扶葆驭，神策驾丰隆。","磐溢铜仙露，窗含玉女风。","青泥分太液，紫气接居庸。","净可捐烦虑，温能养圣躬。","醴源逢处合，仙井凿来空。","衣藻沿涡碧，岩花入照红。","潆阶将赴壑，听水似呼嵩。","钟乳浮银碗，松云锁玉栊。","起居长乐辇，扈从华清宫。","舜德时存坎，汤田岁转丰。","《甘泉》徒有赋，未敢拟扬雄。"]},{"t":"禹庙","f":"七言律诗","c":["夏王四载告成功，别禅苗山起閟宫。","玉帛千秋新祼荐，衣冠万国旧来同。","金书瘗井封泥紫，窆石悬花映篆红。","一自百川归海后，长留风雨在江东。"]},{"t":"江徼怀人","f":"七言律诗","c":["江徼怀人江外台，江流千里重徘徊。","秦人岛屿乘潮上，汉将楼船绕地回。","残垒低连沙树暝，孤城遥傍海门开。","西陵一望滔滔水，不见长帆天际来。"]},{"t":"除夕逢立春效景龙体","f":"七言律诗","c":["椒盘柏酒傍江开，彩杖青旂出郭来。","玉历乍看今夕换，苍龙先遣隔年回。","林彫朔雪惊抽蕙，地近南天早见梅。","添岁并为除岁日，他乡何似故乡杯。"]},{"t":"少年","f":"七言律诗","c":["少年仗剑出关中，羽卫新招六郡雄。","久许报恩逾聂政，平时饮酒笑秦宫。","鸡鸣晓日黄河动，雁阵秋阴紫塞空。","当日枌榆迁欲尽，愁君驰马过新丰。"]},{"t":"马迹怀南土","f":"七言律诗","c":["越王山下赋离群，英布城前看落云。","岁暮他乡还作客，春来何处不思君。","天开婺女摇晴翠，水满康郎漾夕曛。","阳雁欲归愁未得，几回哀响梦中闻。"]},{"t":"朔方","f":"七言律诗","c":["天校神兵罢朔方，双鞬不复挂渔阳。","三秋白草缘关断，万里黄河入塞长。","铁柱分标滇外戍，金书异姓汉中王。","从军久负匡时略，愁见开边到夜郎。"]},{"t":"寒食渡江","f":"七言律诗","c":["吴关千里燧烟通，挂去长帆返照中。","三月暮春行海畔，两年寒食渡江东。","风吹官柳城边绿，雨后山花陇上红。","惆怅故园年少在，斗鸡蹴鞠与谁同。"]},{"t":"舟过渔林关望沈功宗墓","f":"七言律诗","c":["落日渔林放棹迟，故人宿草望离离。","深怜子敬琴亡后，恐负桥元车过时。","江阔市亭环废井，关长贾舶近荒祠。","难寻下马陵前路，肠断胶西君不知。"]},{"t":"钱唐逢故人","f":"七言律诗","c":["西泠咫尺是天涯，喜汝从予江上槎。","两度陶朱思返越，百年张俭竟无家。","乡关恨届钻榆节，里巷羞乘广柳车。","壮士不还仍远去，江东兄弟漫咨嗟。"]},{"t":"奉答倪粲原韵","f":"七言律诗","c":["自辞濠上寻中散，曾在梁园赋《子虚》。","入世已无操瑟想，闻君尚有带锄书。","东田秋到花开后，西浦人逢落雁初。","只道乘风应万里，相看犹是旧蒿芦。"]},{"t":"览镜词","f":"五言绝句","c":["渐觉铅华尽，谁怜憔悴新。","与余同下泪，只有镜中人。"]},{"t":"长门怨","f":"七言绝句","c":["玉殿金釭晚色新，殿前少使绣麒麟。","夜来恐索长门锦，要赐平阳歌舞人。"]},{"t":"饮马城边曲 其一","f":"七言绝句","c":["燕台北望蓟城山，饮马城边驱马还。","前度锦车休出塞，将军近在草桥关。"]},{"t":"饮马城边曲 其二","f":"七言绝句","c":["城边饮马莫辞遐，将采燕山二月花。","日在阵前谁见敌，蓟门关外尽风沙。"]},{"t":"赠柳生","f":"七言绝句","c":["流落人间柳敬亭，消除豪气鬓星星。","江南多少前朝事，说与人间不忍听！"]},{"t":"汉苑行 其一","f":"七言绝句","c":["彩燕初翻百子池，宫花齐发万年枝。","但知上苑寒归早，不道人间春到迟。"]},{"t":"汉苑行 其二","f":"七言绝句","c":["秋风歌罢柏梁材，上苑春回承露台。","朝来殿使探莺去，日暮宫官试马来。"]},{"t":"除夕作","f":"七言绝句","c":["旅馆椒花红欲然，椒盘愁向客中传。","如何才听金鸡唱，便唤今宵是客年？"]},{"t":"吊姜贞毅诗","f":"七言绝句","c":["曾披阊阖扣天关，垂死孤臣未赐环。","遗命一棺何处葬，宣州城外敬亭山。"]},{"t":"南歌子 其一","f":"古风","c":["铁镬生梁子，铜枢种枣花。","杨柳正藏鸦。","闭门春昼静，是谁家。"]},{"t":"南歌子 其二","f":"古风","c":["茜染墙头草，乌飞陌上桑。","三十侍中郎。","自矜拖紫绶，茜花香。"]},{"t":"南歌子 其三","f":"古风","c":["蕙幌春前雨，花竿晚后虹。","解珥坠青虫。","去年曾借宿，宋家东。"]},{"t":"南歌子 其四","f":"古风","c":["蕊扑鸦头浅，鬟梳虿尾轻。","镜里未分明。","匀残红粉絮，挂帘钉。"]},{"t":"南歌子 其五","f":"古风","c":["高屧宜墙窄，长裙爱裥多。","风起动江波。","隔江风更急，奈裙何。"]},{"t":"南歌子 其六","f":"古风","c":["旧苑罗罗在，新教略略成。","殿上暗呼名。","镀金黄甲子，堕银筝。"]},{"t":"荷叶杯 其一","f":"古风","c":["双桨红船欲度。","荷路。","向前溪。","叶摇倾下露珠子。","菱刺。","又牵衣。"]},{"t":"荷叶杯 其二","f":"古风","c":["五月南塘水满，吹断，鲤鱼风。","小娘停棹濯纤指。","水底。","见花红。"]},{"t":"章台柳 其一","f":"古风","c":["杨柳枝，莫教折。","留绾衫前散巾结。","只恐飞花上紫纶，认作摇郎鬓边雪。"]},{"t":"章台柳 其二","f":"古风","c":["花漏深，春睡醒。","二五窥蟾半边影。","烧残蜡泪泛铜盘，一尺珊瑚沁心冷。"]},{"t":"南歌子 其一","f":"古风","c":["燕尾捎轻雾，花柎涌落潮。","朝鲜计吏附书遥。","三月隋堤、杨柳暗河桥。"]},{"t":"南歌子 其二","f":"古风","c":["驱马东郊道，提筐南陌头。","桑枝欲尽且移钩。","日暮蚕饥、归去好难留。"]},{"t":"南歌子 其三","f":"古风","c":["蜡晕眉间粉，裙萦履上珠。","阳云楼上教歌殊。","吹暖凤梢、双籥卸唇朱。"]},{"t":"南歌子 其四","f":"古风","c":["涩杼嫌经密，残丝畏镊欹。","织缣织素总难期。","独对支机彩石、有谁知。"]},{"t":"南歌子 其五","f":"古风","c":["溘匝箱金断，青红钿晕残。","狂夫塞下几时还。","时见琐窗、蜿蜿坠双环。"]},{"t":"南歌子 其六","f":"古风","c":["掬溜愁蘋捲，投竿喜藻开。","莲舟棹女夜归来。","争照水中、髻子落金钗。"]},{"t":"摘得新 其一","f":"古风","c":["河没时。","霜繁月已低。","错惊银槅曙，起来迟。","扶上鬓梢随意绾，乱丝丝。"]},{"t":"摘得新 其二","f":"古风","c":["日满檐。","虫飞逐槛边。","红衫腰后结，洗妆铅。","指拂额黄时转侧，镜台前。"]},{"t":"摘得新 其三","f":"古风","c":["欲上床。","卸头留半妆。","残膏衔兽颈，且缝裳。","晶环绕指先知冷，偎谁傍。"]},{"t":"摘得新 其四","f":"古风","c":["漏壶移。","还将绣谱披。","碧窗连锁下，响朝鸡。","坐得画裙千百褶，夜何其。"]},{"t":"潇湘神 其一","f":"古风","c":["湘渚头。","水北流。","麦天风雨绿崖秋。","蕉叶缉纱仍染绿，荆门红树好生愁。"]},{"t":"潇湘神 其二","f":"古风","c":["邛竹枝。","生古祠。","丛丛峭壁鹧鸪啼。","朝雨过来还暮雨，不知神女几时归。"]},{"t":"蕃女怨 其一","f":"古风","c":["吴蛾窈窕初拂舞。","堂下春雨。","柳垂鋋，花转毂。","暖翻红烛。","只怜却舞汗衣干。","又春寒。"]},{"t":"蕃女怨 其二","f":"古风","c":["胡腾起作石国语。","愁杀番女。","罽靴尖，铜带软。","蹴踏宛转。","回头忽忆旧安西。","两眉低。"]},{"t":"忆江南 其一","f":"古风","c":["江上路，横曼小长干。","日炙水花红滟潋，烟浮堤草绿绵蛮。","高阁尚春寒。"]},{"t":"忆江南 其二","f":"古风","c":["江路远，草际暗尘消。","红药园深朝坠露，白苹渚浅夜添潮。","人醉画栏桥。"]},{"t":"忆江南 其三","f":"古风","c":["堪忆处，曲巷试单衫。","菱井啄泥悬社燕，桃根熨火种春蚕。","风景是江南。"]},{"t":"忆江南 其四","f":"古风","c":["风景好，菰叶满横塘。","碧带帩头骑马客，红钉屐子拢船娘。","两两见鸳鸯。"]},{"t":"忆江南 其五","f":"古风","c":["临大道，金碧绕天涯。","出郭危楼云作埒，抱江小槛幔垂沙。","记得那人家。"]},{"t":"忆江南 其六","f":"古风","c":["前浦去，何处最能留。","黄鸟换枝啼不歇，落花细逐往来舟。","微月上汀洲。"]},{"t":"忆江南 其七","f":"古风","c":["妆裹淡，时世在江淮。","裙褶缓韬双笼袜，髻根松贴两梁钗。","驱鸭去还来。"]},{"t":"忆江南 其八","f":"古风","c":["频怅望，耶水与梧宫。","谁浣素纱窥越女，因歌白苎号吴侬。","总在石莲东。"]},{"t":"忆江南 其九","f":"古风","c":["归去好，长听子规啼。","红藕城桥风脉脉，黄梅江阁雨凄凄。","愁思望中迷。"]},{"t":"忆江南 其十","f":"古风","c":["江上市，帆落度桥来。","两岸娼楼悬水栅，平船击板瞑烟开。","渔火夜相猜。"]},{"t":"忆江南 其十一","f":"古风","c":["芳草软，朝暮籍车轮。","鸲鹆早寒调婢子，琵琶夜雨赛姑神。","愁杀浪游人。"]},{"t":"思帝乡 其一","f":"古风","c":["拨捩迟。","歌挑舞又催。","半折红衫遮柱，柱初移。","慢揳银彄弦急，恐难支。","不念中宵起，上弦时。"]},{"t":"思帝乡 其二","f":"古风","c":["红帉。","紫帉蓝绿帉。","翠帽玉铃珠串，压金裙。","垂手正巾徐步，毯毛深未分。","倏见暖风吹绕，一堂云。"]},{"t":"思帝乡 其三","f":"古风","c":["霓裳。","羽衣谱未详。","玉貌何人无力，绕珠珰。","曳得钿缨累累，履跷裙自扬。","犹自曲终徐立，听声长。"]},{"t":"浪淘沙 其一","f":"七言绝句","c":["仙橘山前看橘花。","单衫裁就橘山麻。","春江空作揉蓝色，浪里淘来那得纱。"]},{"t":"浪淘沙 其二","f":"七言绝句","c":["杉木为箄竹作檐。","江潮能苦雨能甜。","连朝只饮檐头雨，翻道江潮错着盐。"]},{"t":"南乡子 其一","f":"古风","c":["蕉叶领，橘花翘。","红藤篾子束裙腰。","私念鵔鸡颜色好。","从谁道。","栽作大郎头上帽。"]},{"t":"南乡子 其二","f":"古风","c":["藤菜暖，荔枝乾。","青蛉河畔碧鱼餐。","愿绞桄榔皮里肉，炊乌木。","暂与小郎充晚腹。"]},{"t":"南乡子 其三","f":"古风","c":["赛起祠丛。","木棉花发野椒红。","记得丁郎山下路。","敲铜鼓。","九孔红螺扇遮舞。"]},{"t":"南乡子 其四","f":"古风","c":["卢橘催酸。","风生蒌叶瘴烟寒。","自卖明珠归极浦。","心苦。","白氎单衫着秋雨。"]},{"t":"甘州子 其一","f":"古风","c":["银床金井晓啼鸦。","帘额上，衬红霞。","同心栀子夜开花。","和露折来斜。","无好意，送与谢娘家。"]},{"t":"甘州子 其二","f":"古风","c":["织金衫重懒提笔。","双扼臂，卸来轻。","平头吹蜡炙铜笙。","叶底弄莺声。","无好意，唤与顺郎听。"]},{"t":"江城子 其一","f":"古风","c":["赭门东上海潮青。","古西陵。","雨冥冥。","越王宫女，着履在樟亭。","亭下教兵遗竹矢，秋日晚，堕鸦翎。"]},{"t":"江城子 其二","f":"古风","c":["日出城头鸡子黄。","照红妆。","动江光。","采莲江畔，锦缆藕丝长。","欲问小姑愁隔浦，长独处，久无郎。"]},{"t":"江城子 其三","f":"古风","c":["江深不畜伺潮鸡。","春和出户迟。","浣纱稀。","双桥钗子，填粟缀红泥，裁得荷花新样好，羞比着，嫁时衣。"]},{"t":"杨柳枝 其一","f":"七言绝句","c":["花萼楼前杨柳枝。","美人剪綵自寻思。","千丝万丝谁作样，剪来总似一条眉。"]},{"t":"杨柳枝 其二","f":"七言绝句","c":["白蝶爱翻轻粉絮，黄鹂偏上缕金条。","双眉桑叶凭君看，无奈低边是细腰。"]},{"t":"踏歌词 其一","f":"五言古诗","c":["园里花成子，梁间絮作泥。","风鸢移柱线，云母贴窗衣。","漫摘鬓边篦，上有闹蛾儿。"]},{"t":"踏歌词 其二","f":"五言古诗","c":["网户黏虫翅，帘旌压柳条。","整钗时对镜，结襻屡回绦。","漫折井边桃，上有合欢梢。"]},{"t":"天仙子 其一","f":"古风","c":["蜡炬乍开红芍药。","枝头又噪星桥鹊。","还疑荡子早归来，蛛网错。","勾眼角。","昨晚下阶裙带落。"]},{"t":"天仙子 其二","f":"古风","c":["玉茧牵丝缠宝帔。","当胸绣出承恩字。","朝朝独自捲衣裳，蜥蜴尾。","长绕臂。","谁识床头有龙子。"]},{"t":"天仙子 其三","f":"古风","c":["珠雀五层宫髻直。","红绦盘委花砖级。","太平天子用恩多，草露潗。","裙裹湿。","犹许蜻蜓上裙立。"]},{"t":"天仙子 其四","f":"古风","c":["墙里花枝墙外影。","嘶騧缓踏飞花冷。","隔墙见得不分明，金甃井。","银络绠。","井面看身见斜领。"]},{"t":"天仙子 其五","f":"古风","c":["新殿前头骑马去。","射生籍里名初注。","红裆垂镫手垂丝，回盼处。","风绕絮。","羞抱夹金鞍子住。"]},{"t":"天仙子 其六","f":"古风","c":["鱼网劈来螺粉滑。","臂痕细压金条脱。","背人写就两行欹，花胜缬。","银缕结。","纤指斜封惹脂沫。"]},{"t":"天仙子 其七 蠡城为王郎记事","f":"古风","c":["城上春云城下雨。","倩人留婿倾春醑。","偷将婿袷障春寒，烹雪黍。","炊玉杵。","调婿乡音隔窗语。"]},{"t":"天仙子 其八","f":"古风","c":["针管红抽丹凤锓。","螭头金错裁双枕。","谁家白苎夜歌来，人未寝。","霜又凛。","误剪葡萄紫丝锦。"]},{"t":"天仙子 其九","f":"古风","c":["斑簟纹生双腕缬。","梦中欲笑开娇靥。","醒来记得许多情，檀兽爇。","钗燕热。","侍婢相看那能说。"]},{"t":"长相思 其一","f":"古风","c":["长相思，在春晚。","朝日瞳瞳熨花暖。","黄鸟飞，绿波满。","雀粟衔素珰，蛛丝断金剪。","欲着别时衣，开箱自展转。"]},{"t":"长相思 其二","f":"古风","c":["长相思，在秋节。","复斗垂垂怨蜻蛚。","锦纹砧，素丝镊。","梦苦见参星，关深落榆叶。","欲识夫婿寒，花阶映微雪。"]},{"t":"遇陈王 其一","f":"古风","c":["枇杷花里谁家院，近丛坛。","青漆左厢开绣户，坐双鬟。","着地画帘飞燕燕，当阶碧草映兰兰。","车轮未必成三角，叉住门边那得还。"]},{"t":"遇陈王 其二","f":"古风","c":["阿侯十六南邻女，对门居。","相视欲申无限意，口中朱。","朝起青烟萦兽爪，晚来红烛透虾须。","牙箱实裹冰蚕茧，骨里相思岂是虚。","·金斗熨开鱼子襭，衬红裳。","铜瓶注暖狮头炭，理黄妆。","频呼小玉因声巧，欲写泥金恐恨长。","那见瑶台成粉幛，果然银汉是红墙。"]},{"t":"酒泉子 其一","f":"古风","c":["风搅红帘。","愁损隔帘人影。","倩秦娥，缠越苘。","唱吴盐。","黄铺白锁春相望。","高阁魂惊难上。","那更堪，花满桁。","柳垂檐。"]},{"t":"酒泉子 其二","f":"古风","c":["可惜春归。","换得好花成叶。","启金箱，叠絮褶。","熨单衣。","银钩翠笼南邻女。","日暮采桑西去。","怕秋胡，回道路。","返迟迟。"]},{"t":"酒泉子 其三","f":"古风","c":["宁扫空床。","怕见满栏月色。","写金针，萦象尺。","坐灯凉。","屏欹漏月灯犹悄。","坐远影儿较小。","为孤单，长伴晓。","似双双。"]},{"t":"懒卸头","f":"五言律诗","c":["纠纠珠臂绳，宛转辘轳上。","那知双穗条，夜夜空垂帐。","楚雀缘钗桥，胡蜂咂衣桁。","制得懒卸头，殷勤与谁唱。"]},{"t":"定西番 其一","f":"古风","c":["校尉新开疏勒，旋右地，返轮台。","未归来。","夺得燕支万里，草青春已回。","谁道于阗还有，野花开。"]},{"t":"定西番 其二","f":"古风","c":["月落武阳碑下。","控鹊血，挽牛螉。","看烽红。","夜半军中女子，鼓声寒不雄。","恰是深闺人去，梦魂中。"]},{"t":"醉公子 其一","f":"五言律诗","c":["是谁过上苑。","试马归来晚。","双镫武威铜。","樱桃马颊红。","百枝灯并起。","解马归花里。","花底碎金篦。","珊瑚错燕泥。"]},{"t":"醉公子 其二","f":"五言律诗","c":["杏园初试酒。","挟弹遮杨柳。","醉里困金吾。","教姬倒玉壶。","绶丝如鹝子。","翠帢团团刺。","花片缀衣巾。","衣花看转新。"]},{"t":"生查子","f":"古风","c":["绿柰匝茱幮，皂角穿萝屋。","犀槅钉明螺，眼底分朝旭。","沅浦长，淇水曲。","处处难追逐。","欲见有何由，簳蜡成红烛。"]},{"t":"浣溪沙 其一","f":"七言古诗","c":["碧玉蒲芽短短针。","雀罗波底刺当心。","拔蒲归去水淫淫。","楫染绿苔疑掩袖，幔漂红露似湔襟。","晚风吹转北塘深。"]},{"t":"浣溪沙 其二","f":"七言古诗","c":["溪女妆成出若耶。","芹丝萍蔓逼流斜。","青苔石上浣新纱。","爱把单鬟捎竹叶，羞将双脸近荷花。","缇油前覆夜来车。"]},{"t":"浣溪沙 其三","f":"七言古诗","c":["软红江波鸭子清。","日迟游女遍江城。","红桥度烛缓相迎。","细马隔裙穿镫子，平船素手拨帘旌。","大堤春日往来情。"]},{"t":"浣溪沙 其四","f":"七言古诗","c":["娇女新妆村艳浓。","四枝鬟插石榴红。","出门还怕隔溪风。","石镜暗飞山后鹊，荻屏销画水边荭。","西施台馆碧波中。"]},{"t":"浣溪沙 其五","f":"七言古诗","c":["绿满南园孔雀栖。","重花叠叶不通飞。","小姑独出采蔷薇。","珥底珠儿徒刺脸，带穿贝子恐磨衣。","行行立立自寻思。"]},{"t":"浣溪沙 其六","f":"七言古诗","c":["丛鬓轻笼象格纱。","曲尘巾皱翳朝霞。","愁听江阁按红牙。","簪管枉铰银盖叶，绣床空钉白团花。","游丝飞絮近天涯。"]},{"t":"浣溪沙 其七","f":"七言古诗","c":["水绕空江叶绕枝。","竹郎桥畔豆娘祠。","佳人邂逅最堪思。","烛近只将遮幔子，风前长自敛衫儿。","梨花初落酒阑时。"]},{"t":"巫山一段云 其一","f":"古风","c":["筱壁含烟澹，椒花滴露稀。","风吹细雨晓云低。","十二碧峰迷。","神女祠前泪，清猿峡里啼。","瞿塘新水曲尘微。","行客自依依。"]},{"t":"巫山一段云 其二","f":"古风","c":["寒雨萝衣湿，晴云蕉帔开。","空舲峡下近阳台。","谁向梦中来。","丛笛江妃庙，孤舟新妇隈。","山花石竹不须栽。","看作小姑钗。"]},{"t":"女冠子 其一","f":"古风","c":["上元少女。","谁授玉函金筥。","倚香坛。","画帔藤花浅，雕钟橘乳寒。","南宫除牒子，北斗动幡干。","犹见春归燕，似青鸾。"]},{"t":"女冠子 其二","f":"古风","c":["玄都清晓。","坐间碧堂红草。","女仙家。","玉铪量星豆，金◇煮雪花。","驻颜丹作粉，系肘箓垂纱。","浼浼沟头水，尽胡麻。"]},{"t":"女冠子 其三","f":"古风","c":["上清仙梦。","桄到十三春洞。","玉颜红。","月下随王母，花前别宁封。","黄衶潜解佩，赤舄缓弛弓。","称名多误听，为呼侬。"]},{"t":"女冠子 其四","f":"古风","c":["仙房寂寂。","戏采瑶林珠实。","是何乡。","红尾梢花犬，青衣覆石羊。","鲛丝裁绶短，鹅管呷笙长。","倘得逢燕使，问昭王。"]},{"t":"女冠子 其五","f":"古风","c":["平明受事。","堪惜玉笄初侍。","小茅君。","薄雾笼青鬓，轻烟曳䌨裙。","凤衔琪树荩，虬使玉堂云。","恐逐童男去，思纷纷。"]},{"t":"女冠子 其六","f":"古风","c":["碧箫初弄。","暗想秦楼双凤。","几多情。","玉锲分芦节，金箱贮枣饧。","蕉花含秘阁，松影落层城。","谁捣玄霜尽，见云英。"]},{"t":"女冠子 其七","f":"古风","c":["短花长叶。","到处翠軿相接。","洞中春。","衣炷熬丹锡，唇脂瀹水银。","盘囊闲系虎，麈尾笑遗人。","总隔蓬莱路，也生尘。"]},{"t":"女冠子 其八","f":"古风","c":["金巾姣好。","长佩玉砂瑶草。","受清虚。","妆镜歼山鬼，香奁检道书。","缃眉遮羽盖。","素手涤仙厨。","每当三五夜，望蟾蜍。"]},{"t":"女冠子 其九","f":"古风","c":["赤城紫府。","闲贮玄珑妃女。","小仙才。","节拥蓝丝葆，冠抽绿玉钗。","蜂房融日粉，蝶梦绕天涯。","何事刘郎去，不归来。"]},{"t":"山花子 其一","f":"古风","c":["蝉翅宫绡傅体寒。","琵琶掩面夜歌阑。","插得钿头新拨子，是红蛮。","隔舍紫姑星会浅。","开门乌桕雨啼残。","曾卜金钱今始验，拆和单。"]},{"t":"山花子 其二","f":"古风","c":["小院风摇九子铃。","临河长对牸牛星。","欲上玉机愁杼短，织难成。","掷缕烛翻娇凤出，萦丝泪尽湿花生。","谁道锦文无样子，看回程。"]},{"t":"春晓曲 回文","f":"七言律诗","c":["小屏山上西江曲。","深处落梅寒簌簌。","晓鉴菱开赭粉红，残灯穗卷香脂绿。","草头阶刬袜钗金，花里碧钩幡胜玉。","绕凤双簧蜡炙新，早春惊破霜溪竹。"]},{"t":"木兰花令 回前","f":"七言律诗","c":["竹溪霜破惊春早。","新炙蜡簧双凤绕。","玉胜幡钩壁里花，金钗袜刬阶头草。","绿脂香卷穗灯残，红粉赭开菱鉴晓。","簌簌寒梅落处深，曲江西上山屏小。"]},{"t":"菩萨蛮 其一","f":"古风","c":["含桃着雨花如雪。","井边吹落春云叶。","鹦鹉结钗楼，新娘半上头。","裁衣翻样子。","压线盘金篚。","十五小裙腰。","能留线几条。"]},{"t":"菩萨蛮 其二","f":"古风","c":["山鸡栖罢乌啼树。","迎人烧尽柑红炬。","复钥下铜鱼。","车前一幰除。","褥花尝对缝。","羞见双鸳控。","渐减玉炉烟。","人眠故未眠。"]},{"t":"菩萨蛮 其三","f":"古风","c":["宜城二月莺啼早。","罗敷十五双鬟小。","锦带约桑钩。","使君南陌头。","连钱嘶日暮。","共返宜城渡。","莫是看罗敷。","罗敷自有夫。"]},{"t":"菩萨蛮 其四","f":"古风","c":["轻雷鹿鹿宫车转。","晚凉偷弄邠王管。","双甲小蠀蛦。","黄鹂处处啼。","春风吹欲遍。","尽作西清怨。","暗里换歌头。","伊州似石州。"]},{"t":"菩萨蛮 其五","f":"古风","c":["一株柳树千条叶。","桃根巧向梅根接。","花坞暗相通。","新花隔几重。","宝函春信杳。","水漫红鱼小。","半格轴头丝。","环环无尽时。"]},{"t":"菩萨蛮 其六","f":"古风","c":["日黄不上妆山面，露圆难缀珠帘线。","种得郁金花，将来浸木瓜。","枕屏山六扇，上有江南岸。","岸尽是吴关，关前人未还。"]},{"t":"河渎神 其一","f":"古风","c":["楚雨歇残阳。","满庭新月潇湘。","松花湿影坠山黄。","帝女花竿庙旁。","瑶瑟洞箫来极浦，风吹桂酒椒浆。","夜半烟寒翠敛，几人能上高唐。"]},{"t":"河渎神 其二","f":"古风","c":["丹殿俯嵯峨。","洞庭秋水湘娥。","深房鬼火暗青萝。","呜咽神弦自歌。","文木漆光丝缠腹，蕉花影里婆娑。","只为相思美子，灯前一敛双蛾。"]},{"t":"更漏子 其一","f":"古风","c":["枣屏深，桦烛冷。","复壁照人双影。","鱼坠管，兽衔环。","一床衾枕单。","更漏咽。","楼头月。","偏射小窗明蛤。","红幕掩，鹊桥低。","银河又向西。"]},{"t":"更漏子 其二","f":"古风","c":["小檀槽，新捍拨。","弹就夜堂秋月。","银箭断，玉钗凉。","烛槃红泪长。","寒角动。","霜风送。","惊起金微残梦。","关戍柝，女郎砧。","城南秋渐深。"]},{"t":"更漏子 其三","f":"古风","c":["幔钩绳，复斗穗。","寒夜美人半睡。","云掩絮，月胧明。","枕函亭钏声。","蚕烛耀。","飞蛾绕。","门外乌啼难晓。","燔蕙烬，隐纱笼。","罘罳划碎红。"]},{"t":"更漏子 其四","f":"古风","c":["剪鲛丝，量兽锦。","宽窄灯前自审。","钿尺短，错刀残。","晚来多少寒。","园雾薄。","林花落。","水面星摇池阁。","山犬吠，草虫鸣。","曲房魂暗惊。"]},{"t":"更漏子 其五","f":"古风","c":["井梧阴，庭树暝。","寂寂画栏人静。","蜡子焰，蟹衣筐。","邻家夜绩凉。","芭蕉露。","零如雨。","记得暗中欢去。","宵漏尽，晓钟催。","碧窗殊未来。"]},{"t":"木兰花令","f":"七言律诗","c":["晓莺娓娓流妆阁。","日上烛吹红绣幕。","束将方带玉芙蕖，裹就半韝银芍药。","寻花露冷胭脂薄。","花底暗翻钗子落。","谁开鸳锦抱轻云，误使丁娘枕前索。"]},{"t":"小重山 其一","f":"古风","c":["春殿香销锁碧空。","夜凉宫漏悄、咽铜龙。","银河泻地水漴漴。","妆初洗，残粉腻沟红。","双凤宿梧桐。","小桃金井上、露华浓。","长门枉自闭重重。","珠闼迥，时拂玉阶虫。"]},{"t":"小重山 其二","f":"古风","c":["芳草茸茸翠辇迟。","昭阳初日影、散彤墀。","银幡綵胜戴双纚。","金错小，剪出万年枝。","御苑落花时。","祠前祈百子、汉家池。","承恩唯有臂红知。","中宵梦，频起视胭脂。"]},{"t":"小重山 其三","f":"古风","c":["黄帕衔鳌结象床。","捲衣长拂面、侍君王。","衫襟深惹御篝香。","绡幛影，隐隐见鸳鸯。","别院罢霓裳。","众中新赐着、殿头黄。","年来独系绛纱囊。","江南路，四十杜秋娘。"]},{"t":"小重山 其四","f":"古风","c":["鳷鹊高翾负日温。","春冰融太液、细流浑。","懒调黄子渍香荪。","羊车近，竹叶满金盆。","十载见承恩。","踏青随例出、望春门。","却收银钥暗销魂。","梨花落，深殿又黄昏。"]},{"t":"喜迁莺 其一","f":"古风","c":["榆叶里，楝花前。","烧尽白矾烟。","娇龙自走不须鞭。","最喜是莺迁。","歌羽歌，舞羽舞。","人在掌中飞去。","雾丝裙子本蹁跹。","何处更留仙。"]},{"t":"喜迁莺 其二","f":"古风","c":["杏苑北，曲江西。","残雪尚依依。","轻轮辗絮着人衣。","拊马夜归迟。","蓬宴遥，莲漏浅。","红烛万条深院。","晓来唯听乳莺啼。","移上绿杨枝。"]},{"t":"临江仙 其一","f":"古风","c":["澧浦红兰开日暮，美人倚徙空亭。","幽岩春竹雨冥冥。","长思公子，愁绝翠云屏。","碧水尚传瑶瑟怨，枨枨夜鼓湘灵。","苍梧南去晚山青。","楚江迁客，憔悴不堪听。"]},{"t":"临江仙 其二","f":"古风","c":["秋藕丝裙春树面，龙安寺里为家。","时来空馆倚栏斜。","栏前新水，日日浸桃花。","素手自撩金索动，腕绳轻约红纱。","东风相见各天涯。","道傍愁思，散作日边霞。"]},{"t":"临江仙 其三","f":"古风","c":["高阁近花红影合，绕床还种青梧。","西施娇小似无夫。","黄金梯滑，不见有人扶。","茭叶菱根遮浦暗，含情但采菖蒲。","金阊门外夜啼乌。","女坟前去，寒烛照东湖。"]},{"t":"临江仙 其四","f":"古风","c":["晚渡潮生野火静，丛祠深对江波。","垂鬟接黛一青娥。","宝冠珠络，花帔贴银鹅。","估客往来争祷赛，隔船吹凤鸣鼍。","山低如带水如罗。","螭头黄绢，隐隐画双螺。"]},{"t":"临江仙 其五","f":"古风","c":["睡架荼蘼红刺软，雾中桄蔽轻纨。","几番觅钏坐花间。","香山未暖，石炭捣烟寒。","薄絮装衣萦背胛，空悬辟冻金环。","武溪雪净尚征蛮。","杜鹃声杳，莫是未教还。"]},{"t":"双带子 其一","f":"七言律诗","c":["红藕香销暑殿凉。","玉梭横枕堕钗长。","东楼赋得新来怨，中夜看沉龟甲黄。","黄甲龟沉看夜中。","怨来新得赋楼东。","长钗堕枕横梭玉，凉殿暑销香藕红。"]},{"t":"双带子 其二","f":"七言律诗","c":["君在教头歌昔昔，妓看垂手落掺掺。","裙裥半将遮屐点，柘竿长是拄腰纤。","纤腰拄是长竿柘，点屐遮将半涧裙。","掺掺落手垂看妓，昔昔歌头教在君。"]},{"t":"双带子 其三","f":"七言律诗","c":["楼高是处尽乌啼。","柳外烟同翠眼迷。","流水落花春寂寂，浮家一槛近前溪。","溪前近槛一家浮。","寂寂春花落水流。","迷眼翠同烟外柳，啼乌尽处是高楼。"]},{"t":"双带子 其四","f":"七言律诗","c":["春缸玉酒细鳞红。","怨鸟啼花隔数重。","银子蒜垂帘押静，新开背面两鸾栊。","栊鸾两面背开新。","静押帘垂蒜子银。","重数隔花啼鸟怨，红鳞细酒玉缸春。"]},{"t":"双带子 其五","f":"七言律诗","c":["谁向妆亭亭后别，望中烟雨带帆开。","丝回漫水蓝如袄，黛绕横山青似媒。","媒似青山横绕黛，袄如蓝水漫回丝。","开帆带雨烟中望，别后亭亭妆向谁。"]},{"t":"双带子 其六","f":"七言律诗","c":["红荷短间白荷长。","细细风来细细香。","浓露滑篙联艇侧，同来到处问家乡。","乡家问处到来同。","侧艇联篙滑露浓。","香细细来风细细，长荷白间短荷红。"]},{"t":"双带子 其七","f":"七言律诗","c":["寒雨江汀隔断桥。","去时当似不来潮。","兰浦忆人愁渺目，漫漫夜梦合花梢。","梢花合梦夜漫漫。","目渺愁人忆浦兰。","潮来不似当时去，桥断隔汀江雨寒。"]},{"t":"双带子 其八","f":"七言律诗","c":["鸠浮白水踏歌虚。","鬓捋虫珠雀画裙。","楼上捲裳龙女侍，沟前御宿卸妆初。","初妆卸宿御前沟。","侍女龙裳捲上楼。","裾画雀珠虫捋鬓，虚歌踏水白浮鸠。"]},{"t":"甘州遍 其一","f":"古风","c":["青槐路，迤逦返长杨。","暮云翔。","银鱼立胛，金鹅仗带，曾骑黄马射黄羊。","歌肆侧，酒垆旁。","调鹰牵犬归去，愁杀羽林郎。","花刬帽，往往赌毬场。","暗风扬。","薰衣透缕，隔巷细生香。"]},{"t":"甘州遍 其二","f":"古风","c":["金槌去，长策枣红骝。","五陵游。","纯钩蒯绕，缦胡缨曲，冰梢猎猎似星流。","兄执戟，弟长秋。","射飞逐没尝见，便殿赐衣裘。","年正少，花发醉娼楼。","锦缠头。","几行歌舞，一曲遍甘州。"]},{"t":"甘州遍 其三","f":"古风","c":["甘州遍，羌笛又将残。","听声寒。","黄花碎叶，雕戈铁马，茫茫飞雪满燕山。","边角静，戍衣单。","红闺万里梦断，都护请生还。","雁帛远，风急堕旌竿。","望长安。","甘泉铙吹，何日达萧关。"]},{"t":"甘州遍 其四","f":"古风","c":["秋风起，展转事长征。","出边城。","弯弧鹊角，佩刀犀首，趫趫斥突愿擒生。","收敕勒，捲镵枪。","夜凉频击刁斗，空碛答遥声。","转战苦，车骑未成名。","塞魂惊。","琵琶孤冢，春草日青青。"]},{"t":"十六字令","f":"古风","c":["花下影，跟人上玉墀。","谁推倒，横着半毡儿。"]},{"t":"捣练子 其一","f":"古风","c":["青草软，绿波长。","日暮乡关思渺茫。","吴苑隋堤何处是，满江垂柳又垂杨。"]},{"t":"捣练子 其二 泊山塘作","f":"古风","c":["云淡淡，雨丝丝。","旧日真娘何处祠。","横笛短箫声渐远，藕花塘子夜来时。"]},{"t":"梦江南 其一 当缓缓归曲","f":"古风","c":["临安去，陌上已开花。","扇影似翻江上羽，车帘刚拂草头沙。","缓缓好归家。"]},{"t":"梦江南 其二 当缓缓归曲","f":"古风","c":["临安去，陌上已开花。","绕路烟丝笼暖去，清江日影带潮回。","缓缓好归来。"]},{"t":"法驾导引 送一苓和尚还罗浮","f":"古风","c":["江帆暮，江帆暮。","六月水西头。","竹子牵来黄蛤履，荷花泛去白螺舟。","送汝返罗浮。"]},{"t":"忆王孙 其一","f":"古风","c":["东风吹柳覆金堤。","夹岸红楼望去迷。","日映游丝捲幔低。","画桥西。","一树娇花鸟自啼。"]},{"t":"忆王孙 其二 游西施山","f":"古风","c":["西施歌馆旧城东。","画栋朱栏映碧空。","花絮阴阴趁晚风。","翠重重。","石上胭脂堕雨红。"]},{"t":"一剪梅 其一 剪半","f":"古风","c":["光宅坊前十字街。","桃子花开。","杏子花开。","钿头栎子有人猜。","恐是铜钗。","不是金钗。"]},{"t":"一剪梅 其二 剪半","f":"古风","c":["缚竹纤纤似女腰。","欲上溪桥。","怕上溪桥。","黑云遮住北山坳。","昨日风潮。","今日风潮。"]},{"t":"一剪梅 其三 剪半","f":"古风","c":["木槲花间乳鹊栖。","鹊也能飞。","花也能飞。","临行空记草花期。","二月当归。","三月当归。"]},{"t":"长相思 其一 泛舟西江即事","f":"古风","c":["一桥低。","两桥低。","枣树湾头西复西。","江深雨欲迷。","早乌啼。","晚乌啼。","两桨归来乌未栖。","相逢半路溪。"]},{"t":"长相思 其二 泛舟西江即事","f":"古风","c":["双头钗。","独头钗。","一样金鹅两样排。","钗梁起四台。","乌帽来。","白帽来。","湖就矶头望几回。","菖蒲花未开。"]},{"t":"点绛唇 其一 送春","f":"古风","c":["恼杀啼鹃，逢人还道春归去。","留人不住。","谁要留春住。","花絮茫茫，万点愁人绪。","归何处，春归无路。","莫是人归路。"]},{"t":"点绛唇 其二 姜亦舆汝长庚庚邀听琵琶","f":"古风","c":["抱出檀槽，金丝拨子轻轻落。","浅围罗幕。","月上栏杆角。","夜半嘈嘈，繁手惊相错。","敲银索。","梦回妆阁。","花底飞乌鹊。"]},{"t":"点绛唇 其三 采莲曲","f":"古风","c":["南浦风微，画桡已到深深处。","藕花遮不住。","不许穿花去。","隔藕丛丛，似有人言语。","难寻溯。","乱红无主。","一望斜阳暮。"]},{"t":"相见欢 其一","f":"古风","c":["倚床还绣芙蓉。","对花丛。","牵得丝丝柳线翠烟笼。","愁思远，抛金剪。","唾残绒。","羞煞鸳鸯衔去一丝红。"]},{"t":"相见欢 其二","f":"古风","c":["花前顾影粼粼。","水中人。","水面残花片片绕人身。","私自整。","红斜领。","茜儿巾。","却讶领间巾里刺花新。"]},{"t":"相见欢 其三 怀人","f":"古风","c":["秋风袅袅登台。","强徘徊。","两两鸳鸯飞去几时回。","钱塘路。","西陵渡。","总天涯。","不是早潮又是晚潮来。"]},{"t":"霜天晓角 其一 同丁大声、史宪臣、徐徽之、蔡大敬、来成夫登望京门楼","f":"古风","c":["平沙十里。","滚滚江潮水。","横下秋鹰如削，短草岸，朔风起。","栏杆人共倚。","旧关何处是。","记得西施，去路残阳外，碧烟里。"]},{"t":"霜天晓角 其二 晓起","f":"古风","c":["柳烟如织。","病起逢寒食。","昨夜东风吹紧，花梢上，雨来急。","晓开铜镜立。","镜光涵晓色。","惊见浓云堆下，梨花月，一轮白。"]},{"t":"丑奴儿令 其一 妓席送酒","f":"古风","c":["玉瓶春暖酴醾浅，艳杀青哥。","窄袖摩挲。","早把空杯弄钿螺。","擎来误湿双条脱，重泻金波。","斜对银河。","唱罢甘州奈若何。"]},{"t":"丑奴儿令 其二","f":"古风","c":["珠绳初挂银河泻，花满中庭。","露满中庭。","懒向庭前看月明。","山屏几褶孤眠久，梦也难凭。","醒也难凭。","翻愿今宵梦不成。"]},{"t":"减字木兰花 其一 桑妇词","f":"古风","c":["城南暮雨。","尚有采桑秦氏女。","低系桑笼。","独倚桃花一树红。","青骢西去。","口里衔丝衔不住。","归到灯前。","一任三眠与四眠。"]},{"t":"减字木兰花 其二 同姜八孝廉有访","f":"古风","c":["陆公祠畔。","十里横塘行未半。","花港深深。","王四娘家何处寻。","醁醅初注。","又是孝廉船欲去。","怕照菱花。","对面分明又一家。"]},{"t":"卜算子 其一","f":"古风","c":["小鸟踏花枝，花落如红霰。","花树朦胧一径迷，中有佳人面。","愁见落花多，欲去还留恋。","扇子盛来仔细看，点点桃花片。"]},{"t":"卜算子 其二","f":"古风","c":["门外绿杨堤，门里红妆女。","何处金羁美少年，故绾垂杨缕。","风起搅杨花，飞作廉纤雨。","眼底迷迷不见人，且听黄鹂语。"]},{"t":"阮郎归 其一 春暮","f":"古风","c":["樱桃子熟竹初肥。","南园昼启迟。","蜂房滤粉暗成脾。","画垣生绿衣。","蒲雨涨，柳桥低。","秋千深院迷。","杜鹃啼歇最高枝。","有人还未归。"]},{"t":"阮郎归 其二 秋暮见晓妆者","f":"古风","c":["拒霜花发傍妆楼。","楼前细水流。","隔花初日上帘钩。","美人楼上头。","开碧箧，泻红油。","镜边长坐愁。","鸳鸯瓦热露华浮。","玉钗寒未抽。"]},{"t":"浣溪沙 和任二王辅回环韵","f":"七言古诗","c":["阴柳垂庭山枕斜。","禽鸣自上槛边花。","深屏午梦隔窗纱。","瓮启冰牙蛆泻酒，襟披雪眼蟹潆茶。","临妆晚扫淡黄鸦。"]},{"t":"回前","f":"七言古诗","c":["斜枕山庭垂柳阴。","花边槛上自鸣禽。","纱窗隔梦午屏深。","酒泻蛆牙冰启瓮，茶潆蟹眼雪披襟。","鸦黄淡扫晚妆临。"]},{"t":"武陵春 登仙桃山","f":"古风","c":["溪口桃花红欲暮，浅水泛胡麻。","行尽空林散紫霞。","来到上清家。","缥缈香坛松饭熟，石鼎醉丹砂。","归路残阳噪晚鸦。","回首乱云遮。"]},{"t":"菩萨蛮 其一 即事","f":"古风","c":["花前鼓瑟花间听，红灯低照新妆靓。","侍婢唤行云。","高唐曾见君。","玉笼香雾绕，怕见青铜晓。","井上辘轳声，翻教睡画屏。"]},{"t":"菩萨蛮 其二 咏枕和友","f":"古风","c":["珊瑚镂枕珠阗细。","盘云散泽香衣腻。","枯压鬓边花，花红印一些。","与谁同转侧，绣出双鸂鶒。","将枕付陈思。","陈思思不思。"]},{"t":"菩萨蛮 其三 咏枕和友","f":"古风","c":["嘉文小裹双丝纽。","单窝认得孤眠久。","泪浥口脂融，相逢一梦中。","花函遮短帔，中有相思字。","银烛夜来新，深怜抱枕人。"]},{"t":"菩萨蛮 其四 商霖臣纳姬","f":"古风","c":["沟头流水山头雪。","春江几度迎桃叶。","桃叶渡江来，江花两岸开。","珍珠量几斛，买得双蛾绿。","衫子绿于蛾，双蛾奈绿何。"]},{"t":"菩萨蛮 其五 为杨生催妆者，多见纸落，椽上官知书也。最后弟子周风远，索甡和词","f":"古风","c":["丹枫叶叶迎春小，锦茵开处香鸾绕。","银扇隔雕栊，灯花百子红。","檐前乌鹊曙，休遣催妆去。","赋得夜来珠，昭容揽镜馀。"]},{"t":"菩萨蛮 其六 为杨生催妆者，多见纸落，椽上官知书也。最后弟子周风远，索甡和词","f":"古风","c":["雕篮细压花毬小。","金箱叠锁珠丝绕。","花烛满帘栊，双樽琥珀红。","芙蓉清漏曙，晓凤衔烟去。","慢撒帐头珠，香奁贮有馀。"]},{"t":"菩萨蛮 其七 颠倒韵伯兄大千侄阿莲同作","f":"古风","c":["药栏勾堕衔钗雀。","雀钗衔堕勾栏药。","花落画屏纱。","纱屏画落花。","晓山关雁绕。","绕雁关山晓。","人远惜残春。","春残惜远人。"]},{"t":"菩萨蛮 其八 颠倒韵伯兄大千侄阿莲同作","f":"古风","c":["软铺铜甃飞红浅。","浅红飞甃铜铺软。","深巷柳摇金。","金摇柳巷深。","爚篝香雾薄。","薄雾香篝爚。","门掩半黄昏。","昏黄半掩门。"]},{"t":"菩萨蛮 其九 颠倒韵伯兄大千侄阿莲同作","f":"古风","c":["去春三鸟栖来曙。","曙来栖鸟三春去。","边塞绝秋千。","千秋绝塞边。","错弹哀抵角。","角抵哀弹错。","楼倚谢娘秋。","秋娘谢倚楼。"]},{"t":"菩萨蛮 其十 颠倒韵伯兄大千侄阿莲同作","f":"古风","c":["井干双断金丝绠。","绠丝金断双干井。","城上响啼莺。","莺啼响上城。","绮园南去骑。","骑去南园绮。","迟日坠鸣机。","机鸣坠日迟。"]},{"t":"菩萨蛮 其十一 颠倒韵伯兄大千侄阿莲同作","f":"古风","c":["簸钱金压花裙唾。","唾裙花压金钱簸。","斜日斗钿车。","车钿斗日斜。","酒胡雕列缶。","缶列雕胡酒。","孤独醉当垆。","垆当醉烛孤。"]},{"t":"菩萨蛮 其十二 颠倒韵伯兄大千侄阿莲同作","f":"古风","c":["熨香沉斗珠绳屈。","屈绳珠斗沉香熨。","花鸭睡笼纱。","纱笼睡鸭花。","减丝荷漏浅。","浅漏荷丝减。","长夜好难量。","量难好夜长。"]},{"t":"菩萨蛮 其十三 颠倒韵伯兄大千侄阿莲同作","f":"古风","c":["烛槃深影春围曲。","曲围春影深槃烛。","迷路入花溪。","溪花入路迷。","枕函空覆锦。","锦覆空函枕。","遮莫苦栖鸦。","鸦栖苦莫遮。"]},{"t":"菩萨蛮 其十四 颠倒韵伯兄大千侄阿莲同作","f":"古风","c":["刺桐花满高桥寺。","寺桥高满花桐刺。","魂断几家村。","村家几断魂。","去騧嘶落絮。","絮落嘶騧去。","娘度夜中霜。","霜中夜度娘。"]},{"t":"菩萨蛮 其十五 颠倒韵伯兄大千侄阿莲同作","f":"古风","c":["小姑村映青溪晓。","晓溪青映村姑小。","家是就矶斜。","斜矶就是家。","返舟莲棹远。","远棹莲舟返。","侬识旧娃宫。","宫娃旧识侬。"]},{"t":"菩萨蛮 其十六 寄友","f":"古风","c":["上潮春涨西陵望。","望陵西涨春潮上。","寒雨渡来难。","难来渡雨寒。","燕泥衔断槛。","槛断衔泥燕。","时苦作蚕丝。","丝蚕作苦时。"]},{"t":"菩萨蛮 其十七 访所欢作","f":"古风","c":["路旁厢板乌椑树。","树椑乌板厢旁路。","寻处甚阴阴。","阴阴甚处寻。","缕丝千点雨。","雨点千丝缕。","何若别情多。","多情别若何。"]},{"t":"菩萨蛮 其十八 落帆亭送女士黄皆令远行","f":"古风","c":["窄帆轻落亭前驿。","驿前亭落轻帆窄。","红露浥花栊。","栊花浥露红。","渡淮临雨暮。","暮雨临淮渡。","长过莫愁乡。","乡愁莫过长。"]},{"t":"摊破浣溪沙 怀张七雏隐粤东未归","f":"古风","c":["黄木湾前芦雁稀。","琵琶洲畔竹花飞。","南去陆郎烟瘴里，几时归。","翠鸟羽长临镜远，章鱼海阔跳波微。","看到木棉红又白，好装衣。"]},{"t":"少年游 过陵下感旧","f":"古风","c":["当时邂逅，凌家山下，桃树满前津。","今来又值，桃花开后，不见那时人。","香轮翠幕陵前路，日影动飞尘。","流水横斜，鸟啼哀怨，愁对武陵春。"]},{"t":"南柯子 其一 斗草词","f":"古风","c":["喜摘唯红豆，难攀是白榆。","百花亭外展氍毹。","藏得宜男、临赛又踟蹰。","绡帕牵藤刺，缃襕裹露珠。","朦胧却把翠钿输。","暗拣花枝、插补鬓边虚。"]},{"t":"南柯子 其二 和杨王客赋得玲珑隔窗语","f":"古风","c":["青漆垂银钥，丹纱映玉栊。","隔窗娇立小芙蓉。","两地分明、细语一灯红。","好鸟音初剪，幽兰气转浓。","相看枉自唤玲珑。","一寸明螺、槅子万重峰。"]},{"t":"南柯子 其三 落花","f":"古风","c":["粉蕊飘来薄，红英落处稀。","一团并作屐头泥。","却是桃花飞过、李花飞。","残粉留青蒂，零红断碧枝。","落花那辨早和迟。","空自晓风吹了、晚风吹。"]},{"t":"南柯子 其四 饮龚氏","f":"古风","c":["梧子丛台敞，荷香小幕开。","冰浆雪瀣满樽罍。","时见梁间双燕、自飞回。","覆草传螺碗，藏钩觅坠钗。","闺中柳絮谢家才。","妒煞王郎、私遣隔帘猜。"]},{"t":"鹧鸪天 其一","f":"古风","c":["绛帐迢迢结作云。","东风吹皱石榴纹。","芙蓉弄色调金粉，蛱蝶寻双认绣裙。","花羃历，思纷纭。","游车归去日斜讯。","不知唱得难忘曲，十二钗边若个闻。"]},{"t":"鹧鸪天 其二 过女教场有感","f":"古风","c":["银甲雕戈小队工。","内家宣敕教从戎。","山萝覆镞萦金细，野火烧旗闪幔红。","宫月静，阵云空。","凤凰山下抱龙弓。","珠兜玉靸团营路，小雨寒花何处逢。"]},{"t":"鹧鸪天 其三 赋得鸳鸯沙路远","f":"古风","c":["翠鬣红翘金蹠低。","藕花多处一汀迷。","谁怜比翼琴台瓦，枉织双丝锦字机。","银埒远，玉塘稀。","天长海阔几时归。","相离只解相思死，那解相思未死时。"]},{"t":"鹧鸪天 其四 赋得鸳鸯沙路远","f":"古风","c":["蓼浦兰江隔远涔。","彩毛飞去信音沉。","十三弦上锼金柱，二八丫头琢玉簪。","无处觅，好难寻。","空留双影绣罗衾。","几回欲向沙头路，到得沙头路转深。"]},{"t":"玉楼春 其一 姜汝高公子迎婚武林","f":"七言律诗","c":["梅花开满清江路。","北府夜凉新幰度。","谁开扇上五明罗，只挂灯前九子璐。","西陵水削回潮暮。","双盏乍传天欲曙。","开元新赐小金钱，撒在帐中无觅处。"]},{"t":"玉楼春 其二 八月宿姜真源宪使后院夜饮同小农汝旦作","f":"七言律诗","c":["红蕖小幕开深槛。","微雨乍收凉漏浅。","酒淹垆火带霜吹，风搅浊油和烟剪。","银船交泛明河转，玉树当轩共婉娈。","夜深空忆广陵涛，水绕曲江知近远。"]},{"t":"玉楼春 其三 题诗纬","f":"七言律诗","c":["吴山晓阁妆螺子。","山木倒开蛮镜里。","笔床闲写竹衣红，书带自垂藤菜紫。","机头小轴穿花绮。","纂就散丝盈络纬。","秋波千顷照芙蓉，无数彩云江畔起。"]},{"t":"虞美人 其一 九日蠡城遇雨","f":"古风","c":["龙山秋曙官亭冷。","烟锁茱萸井。","西风吹雨雁南来。","何处还登戏马宋公台。","美人垆下桑郎熟。","细把金钱菊。","辽东皂帽堕堪伤。","不道满城风雨又重阳。"]},{"t":"虞美人 其二 广陵李宗伯寓观女举作","f":"古风","c":["芜城新曲勾栏浅。","覆地氍毹软。","小蛮金管雪儿筝。","二十四桥明月照人醒。","三朝不作衔书凤。","但舞江南弄。","晓风散去彩云愁。","可是竹西歌吹久扬州。"]},{"t":"虞美人 其三 喜来、我平归自江右，寄诗并讯徐大文、张祖望、吴云章消息","f":"古风","c":["布帆婀娜江州至。","贻我相思字。","怀中一日九开看。","记得旧时风雨夜阑干。","潮平若泛西陵渡。","须把滕王赋。","南州榻冷剑城凉。","借问延陵何日下南昌。"]},{"t":"虞美人 其四 寄怀邹吁士","f":"古风","c":["宫莺细啭皇州路。","花暖金盘露。","春风扈从赋长杨。","策马归来重醉酒垆傍。","钱塘五月冰壶晓。","别馆新荷小。","瑶辞百幅重南金。","思煞梁园客子到如今。"]},{"t":"青玉案 其一 渡江有感","f":"古风","c":["夕阳江上丹枫暮。","看车马、纷无数。","当日西施从此去。","城山出海，楼船近岸，中有更衣处。","平沙十里长亭路。","空留得、花如雾。","最恨江流流不住。","暮潮初下，午潮还上，今古西陵渡。"]},{"t":"青玉案 其二 渡江有感","f":"古风","c":["片帆絓处芦花白。","痛年少、经兵革。","庾信江陵归未得。","教兵城下，高迁屯畔，一夜寒涛坼。","东来西往看如织。","问谁是、当时客。","睹此芒芒百思集。","素车何在，乌鸢散尽，犹有人沾臆。"]},{"t":"瑞鹧鸪 其一 合虞美人调和侄阿莲","f":"七言律诗","c":["梨花亸鹊惊春雪，柳曲迎车怯晓风。","篮外蝶衣笼画粉，楼头凤蜡泻珠红。","熏迷银叶怜妆坼，露压金槽滴睡浓。","无奈景阳钟隐隐，数声和月到帘栊。"]},{"t":"瑞鹧鸪 其二 合虞美人调和侄阿莲","f":"七言律诗","c":["春还绣陌桃初落，日映璚绡幕半遮。","黄点额头花胜结，红抽靴子蒯绳芽。","妒蛾筝合矜秦赵，细犊车香绕狭斜。","空有侍中夸易识，难忘一笑在东家。"]},{"t":"瑞鹧鸪 其三 合虞美人调和侄阿莲","f":"七言律诗","c":["吴娃窈窕裁芳纻，楚竹参差聚列星。","歌扇影回屏半褶，舞裙丝挂箔头钉。","觞迎水曲翻龙㔶，车转花梢动鸽铃。","天上旧曾听鼓瑟，归来几度暮山青。"]},{"t":"瑞鹧鸪 其四 合虞美人调和侄阿莲","f":"七言律诗","c":["董贤馆外骄騧骋，班氏门前冷鸟啼。","湘浦芰裳迷蔡北，秦台苏合出乌西。","针萦鸾缕愁丹缠，灯满蚕塸怨赤蹄。","难与故夫携束素，重逢但唱杞梁妻。"]},{"t":"踏莎行 题梅市香奁集后","f":"古风","c":["宝扇横时，玉堂深处。","开奁齐唱金针句。","汉阳少妇解璇玑，孝标令妹工词赋。","郁草名金，柳花成絮。","满阑种就珍珠树。","欲听缑氏海西谣，须寻仙尉江南路。"]},{"t":"小重山 其一","f":"古风","c":["麦垄青青菜垄黄。","野棠花满路、日初长。","谁家女伴斗新妆。","蜂来往，刺得口脂香。","三五映垂杨。","见人还却步、背方塘。","小姑不解断人肠。","看花落，又看浴鸳鸯。"]},{"t":"小重山 其二 秋千词","f":"古风","c":["绣柱红绳曳彩云。","双双悬画板、对斜曛。","风吹袜子小鸦分。","重扶下，低系水罗裙。","天际映虹纹。","抛来香带薄、绕氤氲。","空园人散欲黄昏。","惊鸿堕，花落自纷纷。"]},{"t":"小重山 其三","f":"古风","c":["花里重寻赵璧弹。","流黄朝日映、织初残。","停机暗下理双鬟。","调弦请，莫是喜幽兰。","弦涩苦难安。","机丝曾裂指、沁心寒。","思繁错记写离鸾。","弹多误，频脱指环看。"]},{"t":"小重山 其四 得友书","f":"古风","c":["青鸟衔来双锦鳞。","背人佯撇下、小重茵。","口脂红浅浥香津。","缄题处，印得指螺新。","素字小泥银。","簪花新样巧、卫夫人。","鸳鸯格子剪江蘋。","波纹细，恍见泪粼粼。"]},{"t":"小重山 其五","f":"古风","c":["一过东湖深又深。","石桥啼不断、午时禽。","柳黄曾压绞儿金。","双朱户，流水昼沉沉。","有女暗相寻。","红衣羞泪湿、洗前襟。","东风吹放小桃心。","吹难住，吹落满庭阴。"]},{"t":"调笑令 其一 冯二","f":"古风","c":["怨怨。","柳如线。","清漆鸦头红脰燕。","背人偷弄金条钏。","一曲桃枝相恋。","落花飞满春江面。","飞过春江何限。"]},{"t":"调笑令 其二 胥苓弟","f":"古风","c":["梦梦。","晚花冻。","小妹闺房原解诵。","窥帘偏爱求凤弄。","恰是琴心难动。","琴心袅袅春风送。","岂是琴心难动。"]},{"t":"调笑令 其三 王琴","f":"古风","c":["处处。","绕飞絮。","纱帽郎今何处去。","章台折尽长条树。","樗子街头重遇。","玉瓶金盏灯前注。","愁煞夜乌啼曙。"]},{"t":"临江仙 其一 沈康臣生日，席上作","f":"古风","c":["五月海榴红照眼，美人初佩丹砂。","金堂绮席启朝霞。","暑衣裁葛叶，冰碗浸菖花。","赋就子虚将入奏，汉庭狗监先誇。","秋风锦石动星槎。","但悬金似斗，那羡枣如瓜。"]},{"t":"临江仙 其二 沈康臣生日，席上作","f":"古风","c":["细结五丝仙胜缕，屏间艾虎交悬。","愿郎如虎复如仙。","山公曾典薄，四十正当年。","男子生难跨万乘，也应日数官钱。","他时花拂锦连乾。","欲看三岛雪，更泛五湖船。"]},{"t":"临江仙 其三 送董琴庵司马之任汾州","f":"古风","c":["红旆远迎汾上路，楼船还赋秋风。","儿童骑就竹龙葱。","塞烟含柳碧，关雨坠枫红。","汉相江都三策贵，勿需司马军容。","琴台撤幕敞芙蓉。","高山千万叠，流水两三重。"]},{"t":"临江仙 其四 赠任石友初度","f":"古风","c":["记得蜀葵花发后，一樽长对花前。","鸣鸠初拂杖乡年。","紫?开碧筱，丹灶有青莲。","十亩绮园还自赋，彦升当日诗篇。","玉钩金犗钓鱼船。","枕来沧海外，漱向赤城边。"]},{"t":"蝶恋花 其一","f":"古风","c":["蜡子樱儿飞绿鹊。","午睡裁醒，倚遍雕红药。","青映远山回雨脚。","残虹几晕胭脂削。","满院繁华看渐落。","日暮风生，片片吹来薄。","粘得断丝丝又弱。","重重绊住秋千索。"]},{"t":"蝶恋花 其二","f":"古风","c":["日暖秾桃红照水。","粉蝶飞来，水上衔香蕊。","映水双双低复起。","影儿也在花窝里。"]},{"t":"唐多令 嘲柳儿","f":"古风","c":["隋苑覆依依。","行人迷又迷。","风前空惜好腰肢。","待得长条堪作线，蚕箔下，又缫丝。","折尽渭亭枝。","年年送别离。","满栏空自扑人衣。","待得飞花堪作絮，交领下，暖风吹。"]},{"t":"江神子 其一 送柳儿","f":"古风","c":["红亭细柳碧条条。","解轻舠。","渡春潮。","沽酒帘低，春色满河桥。","送得柳枝南浦去，人渐远，楚天遥。","临行重系绿丝绦。","拂花梢。","望迢迢。","柳絮飞飞，偏惹柘黄袍。","春去那堪还积雪，点点下，未曾消。"]},{"t":"江神子 其二 送柳儿","f":"古风","c":["花衔日色柳衔烟。","画楼前。","水连天。","缓橹轻歌，鸭嘴小娘船。","新载摇郎湖曲里，不愿取，渡头钱。","前山深树有啼鹃。","恨年年。","未归旋。","红板人家，犹自挂秋千。","日薄馀寒春又晚，溪路远，草芊芊。"]},{"t":"祝英台近","f":"古风","c":["画栏低，斜日暮，睡起甚无绪。","蝶蝶游丝，阵阵惹飞絮。","是他梅子生心，樱桃辞蒂，著甚个、五风三雨。","隔墙树。","听叶底鹃儿，不住叫谁去。","看又黄昏，寂寂闭朱户。","夜来明月何如，几时回顾，记不出、初三十五。"]},{"t":"满江红 其一 商雨臣弹琴作","f":"古风","c":["猊火初红，抱绿绮、夜堂三弄。","渐秋老、亭皋木落，晚云流冻。","紫稗霜田翔寡鹄，碧梧凉叶栖雏凤。","似兰娘、峡里听流泉，当时梦。","几曾是，商陵痛。","何须作，雍门恸。","但前轩月下，手挥目送。","三尺冰弦看似雪，有新声、迸入鸳鸯综。","恰七条、总似一条丝，丝丝动。"]},{"t":"满江红 其二 施愚山宪长，招同韦剑威六匠、陈集生、张南士、徐伯调、平载问、过岳王祠，观宋高宗手敕，用文待诏，玉弇州韵","f":"古风","c":["第六桥头，四望里、水青山绿。","柳荫下、幔舟舣岸，管笙低蹙。","过雨晓移东岭尽，清钟午度西林曲。","趁红裙、同拜岳王祠，闲追逐。","双熊仗，排花谷。","交螭字，横荒麓。","启玉函珠玺，凤鸾飞簇。","漫道明湖春去久，听子规、尚叫南枝木。","痛玉毫、散写作南枝，枝枝矗。"]},{"t":"玉漏迟 白门张修崖，京口吕锡馨游越，同人公宴于右军祠下即事","f":"古风","c":["右军祠下路，胜友高朋，一时云集。","修竹崇岩，遥想兰亭当日。","车毂骤如流水，交履舄、满堂笙瑟。","何处觅。","华灯影里，管儿歌涩。","早是千里相思，更命驾能来，四愁都释。","南国佳人，邂逅相逢车笠。","梁苑邺宫难再，金樽满、倒倾安惜。","漏转急。","今夕不知何夕。"]},{"t":"满庭芳 其一 公望遗甡以潞国之琴","f":"古风","c":["汉室淮南，潘封泽潞，红弦久擅空桑。","携来海甸，宝匣散珠光。","碧轸瑶徽矶额，龙门树、斫羽镂商。","人传是，乾清供奉，曾遗赐诸王。","崇祯。","题岁月，横纹印绿，苏带流黄。","自王孙散去，沦落江湘。","故国轩悬何处，烧桐好、付与中郎。","谁知得，红丝系足，还是旧宫妆。"]},{"t":"满庭芳 其二","f":"古风","c":["海燕争春，城乌啼曙，丛丛花满阑干。","虹梁日照，碧叶露初干。","昨夜新衣裁就，薰笼暖、翠簇红攒。","频提视，羞人难著，只说晓妆寒。","长干。","西去路，春江鸭绿，新水漫漫。","早青牛朱毂，骝马金鞍。","江畔垂杨万树，风吹绕、贝带斑斓。","妆楼望，翩跹水底，疑向镜中看。"]},{"t":"满庭芳 其三 寿诸耿衣五十","f":"古风","c":["紫峤鸾飞，银河鹊去，南园长报金卮。","莲塘昼暖，花影散红衣。","种得兔头新熟，闲吟望、绣满町畦。","扶瑶瑟，佳人醉拥，日照画栏西。","回首。","当日事，鸡坛会鼓，鹤市吹篪。","叹蹉跎隔岁，屈指俱非。","但对百城图画，家濒海、有友安期。","凭酣饮，朱颜未老，翘首绛云低。"]},{"t":"满庭芳 其四 听商生徵说弹琴永恩楼","f":"古风","c":["微雨凉收，风翻橡叶，女墙斜点三星。","永恩楼上，蹑履暗中听。","何处瑶琴初发，珠帘外、流水泠泠。","停声久，千崖忽堕，玄鹤舞青冥。","汾亭。","遥奏后，箫怜秦女，瑟怨湘灵。","奈晚风吹角，秋雨淋铃。","此际琴心到处，东家女、谁在银屏。","屏中睡，今宵无梦，有梦也应醒。"]},{"t":"满庭芳 其五","f":"古风","c":["石氏悬楼，王朗开阁，伤心睹此芒芒。","上宫碧玉，本是旧名倡。","穗帐空悬日暮，西陵下、几曲沧浪。","如何地，漳台望久，回首见空王。","双双。","寻侣伴，幽吟梵磬，仿佛伊凉。","把杨枝滴露，暗洗朝妆。","满目天花散尽，云床冷、梦断高唐。","褰帘坐，水田衫子，不叠旧衣箱。"]},{"t":"倦寻芳 寄骆叔夜明府","f":"古风","c":["渭南万里，三载携琴，人诵廉洁。","为葬慈亲，归卧溪山别业。","道场勿辞高士吊，哀来时涌丹徒血。","苦思君，又蹉跎相失，暮秋时节。","游望冷、蔷薇洞口，丝竹萧条，远过前哲。","兔苑鸡场，还揽旧时英杰。","草暖吟成樊水调，花飞梦散华池雪。","听西堂，几何时，又鸣蜻蛚。"]},{"t":"桂枝香 姜桐音芳树斋留别","f":"古风","c":["去冬冬至。","刚雪霁梅花，山楼残醉。","儿女灯前感叹，宛如梦寐。","春来重订王孙约，竟淹留、又攀丛桂。","青阳下榻，玄霜解缆，顷刻间事。","念晨夕、盘餐并对。","更寒雨鸡鸣，暖风花坠。","巴里联吟古调，逊君佳细。","云门旧誓寻难度，顿阳关、衰柳摇曳。","几时还看，宾鸿万里，碧天留字。"]},{"t":"喜迁莺 祝赠","f":"古风","c":["锦堂清昼，恰瑶盏传来，玉荷开后。","齐岱基祥，甫侯嗣懿，盛世相君遗胄。","皇览揆予初度，看綵凤翔云岫。","况世载，有千金一字，国门之购。","前侑歌缓处，脆板清丝，花下排红豆。","竹秀联吟，波流送羽，觞咏兰亭依旧。","当日醉乡何在，教好女揄长袖。","恐有客，饮淳于一石，与君为寿。"]},{"t":"长亭怨慢 赋得春日凝妆上翠楼，和叶蕃鲜","f":"古风","c":["春已暮、画奁频启。","朝日穿来，又在眉际。","◇粉将施，弹绵先拂、镜儿里。","木瓜渍了，又添上、新红子。","为要好情多，还则向傍人、问个匀未。","昼长绣褶暖，换却筛罗浅绮。","薰嫌石叶，叠下郁金细细。","临行道、履线将残，踏不得、楼头新?。","谁曾顾楼前，楼外暮春馀几。"]},{"t":"念奴娇 其一 集张登子南华山馆","f":"古风","c":["兰亭秋暮，眺晴原、并到南华山墅。","画槛横塘看两岸，多少断红残紫。","鳌禁当年，鹭车昔日，休沐时来此。","苍梧颍嗣，至今长读秋水。","闲备彩缆青丝，玉壶携酒处，锦鳞鲜美。","吴下阿蒙何日至，相对邺宫才子，舞凤雄图，放龟遗迹，衰柳频低起。","耶溪相望，不知去几何里。"]},{"t":"念奴娇 其二 示姜芑贻留别","f":"古风","c":["谢庭玉树，乍临风，摇曳，乌衣巷里。","何处羊车还洛市，皎皎双瞳如水。","洗马清神，黄门隽格，少小能文史。","玄亭问字，慨然逢故人子。","相对芳树高轩，青灯残夜浅，流萤娓娓。","转盼河桥解缆去，搴尽江皋兰芷。","燕翼堪怜，凤毛有待，西水浮新芑。","春阳努力，眼中吾且老矣。"]},{"t":"念奴娇 其三 为白孟新仲调母夫人寿","f":"古风","c":["囗囗白下，叹何人、不识白家兄弟。","长者贤良方就辟，仲学孝廉相继。","有母年高，北堂娱养，萱树长芬斐。","及时捧檄，如君孝弟能几。","幸遇八十华辰，称觞远近，各具登堂礼。","曾读前朝党锢传，二白齐名杜李。","滂母贤哉，从容告诫，籍籍盈人耳。","风流无恙，百年今且伊始。"]},{"t":"春从天上来 拟昭君词送友出塞","f":"古风","c":["河水东流。","看万里寒风，塞外惊秋。","谁遣倾国，远嫁边头。","辞凤辇、下龙楼。","记临行上马，赐与锦带工箜篌。","卸宫妆，向深深毳幕，徐换貂裘。","平沙那堪晓发，似露下长门，月堕金沟。","满地燕支，萎红枯紫，巧胜画笔涂勾。","羡年年塞雁，归渡海岸与沙洲。","愿仍还上林旧宿，同叫更筹。"]},{"t":"花心动 寄大敬","f":"古风","c":["蝶里花襕，微雨后、深苑荆桃如菽。","红粉堆边，露琯冰筝，并起是谁华屋。","楝华风发前村暮，空岩畔、有人如玉。","牵萝罢、天寒倚遍，一庭修竹。","私唱开元旧曲。","见林外春红，暗翻秋绿。","昨夜惊乌，梦里还啼，向日对筵蕉烛。","玉猧盘地银丝绕，吹松粉、坠来金粟。","那须听、黄公鸟声断续。"]},{"t":"西河","f":"古风","c":["春后雪。","衫儿因甚难热。","绿丛啼鸟听吹来，嫩簧小舌。","可怜谷雨是明朝，又当花谢时节。","翠蛾子，谁与贴。","雀花镜里谁折。","珠娘西去唱杨枝，怨歌几阕。","长干断处苦相迎，桃根桃树桃叶。","枕屏叠下三四褶。","揽流苏，带子双结。","枉对金缸明灭。","但辘轳井上、咿哑相接。","恰夜乌城头啼歇。"]},{"t":"望海潮 越中怀古，同秦淮海韵","f":"古风","c":["东南都会，会稽形胜，居然晋代风流。","宛委赤书，蓬莱紫气，天连星宿牵牛。","佳境任优游。","向山阴道上，秦望峰头。","万壑千岩，当时曾此镇扬州。","依稀旧迹还留。","怅兰亭人散，蕺里歌遒。","九曲风光，五湖烟雨，望中处处生愁。","时泛小犀舟。","看西施西去，花谢妆楼。","犹见若耶春涨，绿草遍芳洲。"]},{"t":"金缕曲 寿商枢部","f":"古风","c":["正小春花暖。","绣屏开、碧觞乍举，黄眉初展。","玄扈干云太宰后，犹见征南季简。","且载酒、闲听丝管。","绿野早成江上宅，况采芝、旧日商山远。","问海水，几回浅。","古来七十原稀罕。","更菁葱、满庭玉树，雕盂金版。","荀氏八龙齐下食，不羡瑶台琼苑。","是何处、驰归轻幰。","大妇流黄中妇锦，最可怜、小妇调笙缓。","榆历历，枣攒攒。"]},{"t":"兰陵王","f":"古风","c":["想前此。","阁下薇花乍紫。","横栏曲、半臂荔红，卷发新梳理黄子。","按鹍弦第四。","忽地。","吴头楚尾。","看看远、海雁又来，眼底空留数行字。","思量那年事。","不合启厢东，夜雨灯暗，桃花，误赚刘郎至。","奈三载寒食，一朝欢聚，手把窄袜弄花绮。","那知梦儿里。","倚徙。","病初起。","况翠帐寒生，晚秋天气。","暮暮朝朝向谁是。","纵迢递关山，梦魂堪寄。","知他去处是百里。","是千里。"]},{"t":"少年游 其一 汝南官署七夕作","f":"古风","c":["看看又是，银河清浅，织女乍停机。","不知何事，今宵残醉，还听汝南鸡。","庭前瓜果妆成巧，暗里絓蛛丝。","记得年前，小矾山下，乾鹊夜来时。"]},{"t":"少年游 其二 过淮城口占，有序","f":"古风","c":["马蹄才发，阳平门外，望里是淮安。","可怜此地，曾经流浪，一十五年前。","曲江高会知何处，秋水晚生烟。","惟有垂杨，千条万缕，还挂酒楼边。"]},{"t":"少年游 其三 过淮城口占，有序","f":"古风","c":["行来但觅，旗亭旧迹，下马驻城闉。","请看当日，淮流如故，双泪落征轮。","淮阴市上诸年少，相忆总沉沦。","谁料衰年，徵车北去，羞见市中人。"]},{"t":"少年游 其四 题陈检讨小影，傍有侍儿坐蕉簟弄笛","f":"古风","c":["十年苦忆，元龙颜面，梦寐恐难亲。","不虞相见，长安道上，并见在傍人。","停毫一顾踟蹰久，欲待按歌匀，碧鸭消时，红蕉坐去，何处不传神。"]},{"t":"南柯子 其一 题胡明府小像。","f":"古风","c":["江县看花后，山城种柳时。","布袍竹杖鬓如丝。","今日画图相对、系人思。"]},{"t":"南柯子 其二 题寄史蝶庵卷后","f":"古风","c":["水涨芙蓉粉，烟含杨柳丝。","幽人家住五云溪。","行过东坡书院，孝侯祠。","箧有中封帖，吟成东去词。","荆南相望一相思。","恰又晚村花垛，夕阳时。"]},{"t":"南柯子 其三 淮西客舍，接得陈敬止书有寄。","f":"古风","c":["驿馆吹芦叶，都亭舞柘枝。","相逢风雪满淮西。","记得去年残烛，照征衣。","曲水东流浅，盘山北望迷。","长安书远寄来稀。","又是一年秋色，到天涯。"]},{"t":"朝中措 平山堂续词","f":"古风","c":["青山犹在画栏空。","人去夕阳中。","不道十年重到，还披此地清风。","蜀冈无恙，堂成命酒，一听歌钟。","未审后来太守，是谁能继山翁。"]},{"t":"西江月 续东坡词","f":"古风","c":["闻道欧公当日，宾朋载酒堂中。","后来三过有坡翁。","长使林花飞动。","此事已经千载，我来重挹高风。","眼前莫放酒杯空。","恐是东坡残梦。"]},{"t":"虞美人 其一 九日，同姚庸庵、张德远、左夔友诸君，泛湘湖登越王城，和庸庵韵。","f":"古风","c":["平明载酒登高去。","湖畔停船处。","几株乌桕未全红。","犹喜黄花开遍小桥东。","长江一望环如带。","放眼千山外。","开樽更上越王城。","多少夕阳江上晚来晴。"]},{"t":"虞美人 其二 过江寺和友","f":"古风","c":["江郎祠外中秋月。","城角吹将彻。","十年长记此宵中。","豪客相过深巷有微风。","今来君宿耆阍下。","又值中秋也。","题将丽句最纷披。","恍见当时桂树晚依依。"]},{"t":"虞美人 其三 题画为李都官寿","f":"古风","c":["是谁画出潘家果。","百琲珍珠颗。","羡君原是柏梁才。","记取桃梨橘栗李榴梅。","玉瓶金锁琉璃瓮。","且作和羹用。","须知仙树本蟠根。","欲借花前一醉石州春。"]},{"t":"虞美人 其四 早行口占","f":"古风","c":["秋风槭槭敖阳路。","草屋方垂露。","当垆夜起数金钱。","独对寒灯此夜不成眠。","廿年歧路今方息。","又是徵书急。","柳梢斜挂月朦胧。","不信还来骑马月明中。"]},{"t":"虞美人 其五 题瑞梅图，和宣城施少参词。","f":"古风","c":["敬亭四月梅花发。","正值清和节。","慈恩寺里曲江边。","新旧郎君争占一枝先。","红罗欲寄无由寄。","空写泥金字。","楼头长赠碧山云。","恰取花枝中半两平分。"]},{"t":"虞美人 其六 题天台采药图，为淮安刘六皆比部","f":"古风","c":["桃花又发临淮渡。","错认天台路。","行来莫笑太奔忙。","知是赤栏桥畔旧刘郎。","平明入直迥西寺。","幞被双娥侍。","含香谁问夜归迟。","只恐桃花回首望中迷。"]},{"t":"虞美人 其七 为刘比部题天禄阁燃藜图","f":"古风","c":["图书万轴牙签满。","辟蠹烧芸暖。","果然子政是前身。","羡煞当年天禄阁中人。","白云司判西曹事。","薇省曾留字。","胸藏冰照宛如犀。","绝胜西堂终夜对燃藜。"]},{"t":"小重山 自涿州至琉璃河达京，和同行韵三首 其一","f":"古风","c":["草店鸡鸣酒未醒。","马槽听啮粟、渐无声。","灯前盥面促装成。","车尘起，疑在雾中行。","渡水石桥平。","秋风联辔过、涿州城。","乡关回首暗心惊。","遥天尽，愁见一云横。"]},{"t":"小重山 自涿州至琉璃河达京，和同行韵三首 其二","f":"古风","c":["贳酒前庄日渐低。","鞭梢斜挂壁、卸征衣。","同行三俊喜相依。","垂杨下，长许控金羁。","河水碧琉璃。","垆头风物美、近京畿。","徵车欲度日迟迟。","沉吟久，三辅故人稀。"]},{"t":"小重山 自涿州至琉璃河达京，和同行韵三首 其三","f":"古风","c":["阊阖嵯峨天际开。","宾门方四辟、重招徕。","将军才到莫相猜。","诸王邸，谁道买臣来。","九市共三街。","彩云遥起处、见蓬莱。","秋风歌咏柏梁台。","承明内，原有掞天才。"]},{"t":"小重山 其四 题吴江女士沈关关为顾茂伦清绣抱瓮丈人濯足图","f":"古风","c":["欲绣平原几度思。","园蛾初作茧、络成丝。","前溪水满雪消时。","波纹起，绿似小桃枝。","投足散涟漪。","夜来开绣谱、度针迟。","一痕青影暮烟微。","衔丝细，不用洗胭脂。"]},{"t":"小重山 其五","f":"古风","c":["朱颜绿发画图中。","丹砂长饮酒、醉溶溶。","前身王母旧青童。","干将佩，花锷散芙蓉。","羽峤有谁从。","蓬莱刚水浅、渡苍龙。","他年笑入杏花丛。","瀛洲近，折取一枝红。"]},{"t":"小重山 其六 过舒汉雯中书官邸有赠","f":"古风","c":["当日吹篪两渡淮。","感君长贳酒、醉高斋。","十年分手各天涯。","频频望，红叶喜当阶。","高咏谢家才。","綵毫裁诏罢、凤池回。","徵书白首苦相催。","平津第，勿厌故人来。"]},{"t":"明月棹孤舟 题吴江徐检讨孤舟垂钓图","f":"古风","c":["甫里先生何处是。","家住近、垂虹亭子。","著罢新书，开门闲望。","但见一湖烟水。","放棹偶然垂钓饵。","人道是、松陵渔史。","若问羊裘，投竿何所，应在白苹洲里。"]},{"t":"千秋岁 和王丹麓自寿原韵","f":"古风","c":["青幡才换。","又是春过半。","听啼莺，声将变。","能令岁月增，真觉黄金贱。","更那顾，秦王有女将衣卷。","但赴芳林宴。","一任花零乱。","年半百，休三叹。","文章堪自信，富贵非吾愿。","君不见，比来世事皆如幻。"]},{"t":"临江仙 其一 题画","f":"古风","c":["姊妹相逢何处是，朱栏斜倚双桐。","坐来委抱鬓笼松。","画裙欹履窄，金钏隔纱红。","寂寂春园人不到，看时多少朦胧。","绿坡生草细茸茸。","银猊闲戏逐，翻向绿坡中。"]},{"t":"临江仙 其二 申江署中题麻姑献酒图，为丁夫人初度","f":"古风","c":["三月暮春春雨后，申江初放桃花。","忻看锦帨挂官衙。","名姝如谢女，夫婿是秦嘉。","制得香奁妆百福，珠屏烂若朝霞。","麻姑曾过蔡经家。","仙厨将进酒，图上见来么。"]},{"t":"临江仙 其三 徐东建纳姬，自题临江仙词，即用其原调并韵嘲之","f":"古风","c":["何处玉台堪倚镜，徐陵原有新题。","今来同住巷东西。","门迎桃叶渡，人胜苎萝溪。","散掷明珠安有价，无钱多买胭脂。","只愁初制夏侯衣。","茜裙裁剪未，帘外杏花飞。"]},{"t":"临江仙 其四 寿姜绮季","f":"古风","c":["五月榴花开似锦，一尊长对花前。","看看又值杖乡年。","蟠溪多寿考，绮里本神仙。","虽则东方能玩世，无须金马门边。","君身何事不堪传。","吟来忘岁月，笔下有云烟。"]},{"t":"临江仙 其五 田公子二十生日","f":"古风","c":["海上青螣看负角，丹山凤翮初成。","男儿二十建修名。","陆机刚作赋，方朔正谈兵。","自愧蹉跎多去日，羡君先请长缨。","南箕不用咏三星。","锦筵香薤发，官阁早梅生。"]},{"t":"临江仙 其六 贺徐公佑明府举子","f":"古风","c":["客舍灯花开似锦，寒屏有梦惟鱼。","新来喜得弄獐书。","蓝田秋产玉，碧海夜生珠。","绣褓画襕初试浴，遥看紫气充闾。","君家原有旧鹓雏。","他时汤饼会，啼听是何如。"]},{"t":"临江仙 其七 祝蒋文甫寿","f":"古风","c":["洛下久无同甲会，试看江左耆英。","年来七十诵黄庭。","孙芝千朵艳，儿竹万条青。","怪道探书多绿字，闲堂代有传经。","桃花染得綵衣成。","杜陵谁最好，吾爱蒋元卿。"]},{"t":"唐多令 咏窝丝糖","f":"古风","c":["捣尽筁头泥。","春蚕已蜕衣。","片饧里作弹丸儿。","不破弥罗三寸茧，谁解道，一窝丝。","粔妆汉宫遗。","餦餭久未施。","开元宫女尚能为。","今日尚书花餤会，银碗合，使人思。"]},{"t":"菩萨蛮 其一 题蔡天声桃花流水图记年","f":"古风","c":["溪流雨过增新涨。","春山处处桃花放。","中有武陵人。","花前一问津。","幅巾裁白氎。","坐听溪流咽。","写入画图中。","桃花映面红。"]},{"t":"菩萨蛮 其二 淮上阎牛叟娶姬，作词索和原韵","f":"古风","c":["钗头胜字裁方幅。","定情弹作莺萝曲。","闻道薛家来。","灯花夜自开。","清淮一别久。","谁解双垂手。","佛日会摹多。","香山老去何。"]},{"t":"菩萨蛮 其三 淮上阎牛叟娶姬，作词索和原韵","f":"古风","c":["买金欲铸鸱夷像。","频年忆汝江湖上。","何处采名花。","西施不及他。","白头吟自在。","诗寄钱刀外。","恰似遇桓伊。","听歌辄唤时。"]},{"t":"菩萨蛮 其四 索赠","f":"古风","c":["云鬟绾就青鸦小。","春山画得双蛾巧。","衣剪杏黄罗。","红牙试按歌。","锦屏香作雾。","慢把金樽度。","玉暖起烟丝。","申江春去时。"]},{"t":"菩萨蛮 其五 索赠","f":"古风","c":["榴裙绉褶花千裥。","地衣红衬弓鞋软。","银箭下来迟。","当筵舞柘枝。","玉栊华蜡里。","新月胧胧起。","何处最嫣然。","花前一笑间。"]},{"t":"行香子 即事","f":"古风","c":["晚色烟和。","鸟散庭柯。","听街头、击破吹螺。","酒阑送客，夜火星罗。","幡幢引处，看蝶演，似莺梭。","法轮常转，五方何处，现维摩、试问禅那。","作天魔舞，于意云何。","香坛行过，随啸咏，且婆娑。"]},{"t":"蝶恋花 客上海，过杨生玉衡听妓作","f":"古风","c":["寂寂暮春杨子宅。","昔在乌聊，今在申江侧。","座上彩云回锦席。","门前几树桃花色。","乍雨乍收檐溜滴。","坐拥双鬟，为我弹瑶瑟。","醉后倚歌还弄笛。","醒来微月当窗白。"]},{"t":"鹊桥仙 即事","f":"古风","c":["东床先订，西家愿宿，何事穿墉穿瓦。","纵教强委后来禽，却不道、子南夫也。","明府风流、使君潇洒，两断可妻公冶。","莫言河汉鹊桥乖，看合浦、在讼庭之下。"]},{"t":"天仙子 贺生子","f":"古风","c":["韦氏双珠真可喜。","芝兰欲在阶庭耳。","春园况值有莺迁，人道是。","天仙子。","曾见宣尼抱送此。","里号高阳从此始。","凤毛麟角纷纷起。","我来正值浴兰时，看取靧。","金盘里。","半是桃花半雪水。"]},{"t":"青玉案","f":"古风","c":["东扬不用占星婺。","是家有、真贤孺。","曾隔兵戈遥海路。","合州城外，雷阳驿畔，多少仳离处。","千山万水归来喜。","看膝下、人如树。","但得朱颜能久驻。","蟠桃花发，蓬莱水浅，谁道流年度。"]},{"t":"喜迁莺 其一","f":"古风","c":["荷风乍暖。","恰红版桥头，骊驹唱缓。","待诏公孙，弹琴司马，挟策争游上苑。","万里鹏飞在望，看翠幕传金盏。","况前路，有漳台花柳，郦亭丝管。","迤逦揽辔处，大道秋光，不觉长安远。","丞相延来，通侯载去，户外车尝满。","他日玉堂堪继，喜大小皆贤阮。","装衣待，来年红杏，为君裁剪。"]},{"t":"喜迁莺 其二 寄赠陶燕公移居，奉和何毅庵、张迩可原唱韵","f":"古风","c":["隔江人远。","一别几何年，鬓毛都换。","但十柴桑，难寻句曲，到处堪留堪恋。","衣上黄尘不落，望垄首浮云变。","犹相忆，在庐江旧第，芹泥桥畔。","可念书画室，半榻琴箫，几树花零乱。","人寄南窗，诗传北郭，莫道未还东苑。","我亦西泠借住，须有日、烟霞结伴。","邻居好，看墙头过酒，那时相见。"]},{"t":"百字令 其一 客沪上，为王鸿资初度","f":"古风","c":["秋风乍起，桂花时、又是东亭初度。","四十年来弹指顷，阅历山川无数。","倚马成文，磨盾草檄，杀尽中山兔。","侯王以下，一时趋走如骛。","谁道梁苑归来，故人官沪上，欢然相聚。","有弟同行胜小陆，共作平台词赋。","弧矢高悬，长庚何在，遥指星明处。","壮心未已，莫言岁月迟暮。"]},{"t":"百字令 其二 寄寿施愚山少参六十","f":"古风","c":["林花初放，捧霞觞、遥望敬亭山色。","绕地珠绳箕宿转，光满谢公楼侧。","阙里遗贤，石渠继世，曾讲诸儒易。","廿年节度，一身高寄如客。","督学齐鲁之间，湖西作镇，到处称申伯。","天下山川游览遍，无数文章堆积。","前遇吴关，今过瓯海，千里长相忆。","才过甲子，为君重数畴昔。"]},{"t":"绮罗香 用原韵，答赠甬上钱蛰庵见赠","f":"古风","c":["古鄮名家，彭城遗胄，所至公超成市。","文效元和，诗以景龙为体。","论学识、雅似颛孙，羡经术、精于杨起。","第无如、弃世逃名，窜身长向瞿昙里。","君家历世仕宦，况祖祢忠孝，名传黄纸。","每辑残编，尚见泪痕如泚。","寻欢会、偶在申江，叹孤游、有如樗里。","又谁知、廿载相思，见君自此始。"]},{"t":"万年枝 梁司农师六十续娶","f":"古风","c":["蜡尽春还，御河冰未泮，苑枝如沐。","柳又生稊，双雉朝飞遫遫。","花甲周时花烛启，宝帐妆成百福。","由来原有，尚书三娶，东山名族。","万年觞卜。","道从此、天长地久，鸾弦终续。","华帼披来，副髲有珈皆玉。","池上歌添黄竹好，探去金桃再熟。","那弃人笑，桃花洞里、刘郎初宿。"]},{"t":"沁园春 其一 即事","f":"古风","c":["已度三朝，忻逢四并，重对春波。","看杨柳堤边，羽觞泛去，蔷薇洞口，油壁来过。","北地贤宾，江南名士，人物加于晋永和。","况杂坐、有美人相间，齐画双蛾。","兴来酒泻银河。","恰岩畔斜阳照绿萝。","看环拥楸枰，目萦琢石，暗抛博具，指印纹螺。","红袖香生，碧桃花放，此际春光可奈何。","华灯起，见楼头纤月，徐上林柯。"]},{"t":"沁园春 其二 答王西园见赠之作","f":"古风","c":["丁巳之春，我来沪渎，喜遇西园。","念当日闻声，有如日下，今朝高会，竟在云间。","江薛才华，庾徐藻采，所著佳文是偶言。","笺题外，有吹蓬小令，折竹新篇。","桃花初涨平川。","又风起城头扑柳绵。","自画阁摊书，谈深烛下，闲堂赠妓，肠断樽前。","两次三番，风晨雨夕，是处相逢非偶然。","沟头水，问东西会合，知在何年。"]},{"t":"沁园春 其三 送叶天乐游吴门","f":"古风","c":["凉月衔云，清风出谷，秋满人间。","况出水芙蓉，诗篇绝丽，环溪修竹，酒兴将阑。","子羽湖头，伯通桥畔，好友相思尝往还。","扬舲去，见停来顾渚，望去吴关。","横塘暑气将残。","更微雨初过销夏湾。","只陂有鸡栖，人归画舫，丘当虎去，寺在青山。","畴昔曾游，石城深处，夜月清樽酹未干。","歌词罢，向旗亭试听，可有双鬟。"]},{"t":"沁园春 其四 题阎容庵青溪传后","f":"古风","c":["桃叶堤边，琵琶巷里，人字青溪。","本博陵旧氏，愁窥燕幕，汾阳公子，共听乌啼。","春寒愁又度，落尽东园几树梨。","空回首，正江南烽火，塞北征鼙。","相誓盈盈两地。","奈仙源鸡犬望后都迷。","况渚下书沉，误排雁影，章台人去，遗恨桃枝。","隔巷空还系臂，便钿合金钗何处思。","只蛮笺数幅，堪付新词。"]},{"t":"贺新郎 萧山县署赘婿词","f":"古风","c":["正河阳花满。","秋水芙蓉，艳红如剪。","赘婿淳于千里至，早已题诗齐苑。","喜今日、光生银管。","古署催妆开锦席，看一堂、紫罽铺香软。","双盏暮，酌来浅。","万条红烛烧将短。","更庭前、几行画扇，遮来宛转。","洗马文章当日事，乐令风流不远。","况种得、蓝田琼琬。","最羡今宵乘凤处，听秦台、几曲箫声缓。","乌鹊到，喜何限。"]},{"t":"满庭芳 其一 南园公宴即事","f":"古风","c":["初过清明，才逾上巳，群贤高会南园。","花岩接槛，洞口泻红泉。","移得竹厨竹里，雕栏曲、杂坐金钿。","擎觞至，红儿娇小，犹弄剪刀钱。","楼前争作伎，枰楸壶竹，游咏依然。","看玉钗纷絓，芗泽微传。","醉煞兰亭旧侣，华灯外、新月纤纤。","当筵赋，园如金谷，人似永和年。"]},{"t":"满庭芳 其二 为汝南张广文题传奇卷首","f":"古风","c":["夏里开基，清河启郡，曾燃秘阁青藜。","高斋寂静，夜听汝南鸡。","仿佛神人告语，他年事、枕畔留题。","长弓后，貂蝉奕叶，不数旧关西。","黄梁炊未熟，翩翩蝴蝶，醒后多迷。","托梨园象板，羽殿铢衣。","千载凤鸾佳配，华茵暖，共酌玻瓈。","听吹罢，一声长笛，无数彩云飞。"]},{"t":"满庭芳 其三 题玉妃献册图，为汝宁金使君夫人生日","f":"古风","c":["琳畹琼妃，瑶台金母，当年曾驾蟾蜍。","因披玉册，还御五云车。","絓去庐江锦帨，闺房秀、早被霞裾。","淮西路，春城千骑，夫婿上头居。","五花裁作诰，香奁百琲，总是珍珠。","看平头擎履，编齿吹竽。","献得龙泥旧简，传经后、莫问居诸。","闲相视，山桃片片，飞满玉床书。"]},{"t":"貂裘换酒 题吴宝崖停鞭拂剑图，和其自题原韵","f":"古风","c":["想此为图者。","计生平、嵚嶙垒落，未经挥洒。","富贵何时思量起，凡事尽如此画。","纵满地、才源倾泻。","但频年驱驰南北，到头末、抹却当时话。","惟此剑，镇无价。","从前只向车前挂。","看中原、平沙万里，尽堪驰马。","建礼门边题名后，便到晾鹰台下。","且自解、双环重把。","多少英雄今安在，遇甘蝇、莫折飞蓬射。","穷与达，有时也。"]},{"t":"念奴娇 其一 即事","f":"古风","c":["申江官舍，看桃花开后、柳丝如织。","伯始风流才启宴，此夜刚逢寒食。","烛下新妆，榴裙百褶，翻尽深红色。","那堪小妓，病来歌舞无力。","听莲漏将残，玉觞娇泻去，唇脂俱湿。","夜雨初过花毯上，尚见翠钿狼藉。","明日清明，来朝上巳，到处春堪惜。","勾栏未散，慢言今夕何夕。"]},{"t":"念奴娇 其二 徐都官裁枕函实诗，名为诗枕。制词索和，漫次其韵","f":"古风","c":["撚髭无计，唤奚儿、长向水边山麓。","蒲簟横陈将偃息，好句吟来断续。","授册嫌频，开椷已缓，纸片纷零碌。","游仙欹处，斲成五色文木。","试启小篦中空，方襕连衽，大似青油袱。","豹首鸡鸣俱不用，但取便便豕腹。","梦去无论，醒来何事，栩栩相追逐。","蝶庵诗就，此时午睡方足。"]},{"t":"桂枝香 即事","f":"古风","c":["夜堂听伎。","正绛帐花垂，玉炉香细。","莲炬光中，两两舞裙拖地。","忽来金雀鸦鬟小，算才堪、琐儿年纪。","栏边歌缓，油车暗里。","翻然而至。","便手把、金樽徐递。","似嫩叶裁衣，幽兰吹气。","病起迟来问取，小名尚未。","风流京兆偏怜惜，道延年、女第如是。","珊珊可念，何如竟唤，翩来为字。"]},{"t":"满江红 题吴墨舫桃源图，步原用文待诏韵","f":"古风","c":["图画当年，正桃树、生花时节。","有延州高士，酒颜方热。","南浦风光何所似，西畴兴会由来别。","恰闻人、洞口忆当年，频频说。","舟过处，涵冰雪。","花落尽，同榆荚。","叹青芝白鹤，一时都绝。","凡事总随风里絮，披图恍对云间月。","幸前贤、手泽有传人，思来切。"]},{"t":"水调歌头 咏鹿脯","f":"古风","c":["加豆得乾腊，酾酒莫踟蹰。","奈何置身岩谷其命在庖厨。","不是笼驴炙豕，岂是牛犓鹅胛，此物本清虚。","但束白茅去，安问绿蕉无。","人一食，寿百岁，试何如。","陈蕃设脠，相食慢作鲁公书。","皮不必为藻币，肠不足为酒器。","祗噬此些须，客座手能擗，何用倩麻姑。"]},{"t":"云仙引 寿王鄂叔进士","f":"古风","c":["兰渚亭边，莲河桥畔，高门乍启朝阳。","单绂绕，彩云翔。","云是揽予初度，争献仙人九酝觞。","何限才名，今才四十，江左王郎。","宫衣试着来长。","有花下、新裁小乐章。","回首京华，难兄执戟，同是东方。","待补山公，正当典簿，努力功名看未央。","他日乌衣，黑头还聚，重醉秋光。"]},{"t":"上西平 谭开子贻画并赋西平乐词，见讯志谢","f":"古风","c":["叹年华，看不尽，短亭花。","更冬残、雪后停车。","问谁相忆，寄来满幅是烟霞。","分明指有，西陵渡口人家。","沧洲近，知何处，空历遍，路途赊。","念君也、留滞西平，思时便望，望时还见暮云遮。","何年携我，向青山、麓碧湖涯。"]},{"t":"庆清朝慢 湖墅高会，同王丹麓、陆荩思诸公即席","f":"古风","c":["候属添丝，人方系缆，还逢高会南皮。","闲堂夜来红烛，倒映金卮。","争投博箸，妓帘不挂夏侯衣。","频倾看，有葡萄酿，色似胭脂。","夙昔只愁间阔，长从纸上，汗漫寄相思。","今夕不知何夕，能预斯期。","城头紞如五鼓，傍筵耿耿玉绳低。","那堪与，曹刘沈谢，即席为词。"]},{"t":"醉蓬莱 题赠徐涵之小蓬莱别业","f":"古风","c":["是南州高士，东海名家，西河旧里。","茅屋数椽，纵亭台无几。","墙外疏桐，檐前蔹蔓，到处成阴翳。","人道蓬莱，逍遥散诞，不过如此。","堪叹年时，燕齐吴楚，汗漫天涯，倦游知止。","一任人间，似桑田海水。","家有山妻，门无杂客，架上馀书史。","安乐窝成，吾其从老，于是乡矣。"]},{"t":"兰陵王 别谭开子","f":"古风","c":["淮南路。","正值嵩阳归去。","梨花晚、寒食初过，与汝东湖最深处。","夜凉倾斗醑。","听拨银筝无数。","扶红袖、酒醒回时，长是城头鼓声曙。","恨一别如雨。","更南北东西，春还秋暮。","许昌宫里留君住。","任作赋繁台，题诗梁苑。","何期此地复相遇。","仿佛似前度。","看舞。","郡中署。","便图遍屏山，歌残烛树。","送君还上棠溪渡。","望长淮千里，依然东注。","那堪言别，况绿柳，渐飞絮。"]},{"t":"风流子 答和桐城何令远见寄","f":"古风","c":["浮山如在眼，枞阳路、时望大江遥。","想当日长瑜，曾为四友，今闻子季，仍号三高。","从谁道，十年黄令阁，一别湛郎桥。","湖上风光，全随蓬转，江南春信，半在梅梢。","幸新来无恙，词中尚记得，醉卧干蕉。","不道安成前度，良夜迢迢。","自白鹭洲边，歌残纤月，红螺泽畔，酒散寒潮。","试问梁园宾客，谁忆枚皋。"]},{"t":"南浦 和徐西崖赠别","f":"古风","c":["最伤心处，是红亭、载酒上河桥。","多少画栏杆外，杨柳正垂条。","五两南风欲度，趁申江、几曲暮归潮。","奈离筵人散，赠鞭情重，双泪落征袍。","此地遨游堪恋，遍亭台、春意闹花梢。","长载佳人油壁，深夜教吹箫。","况值歌成南浦，也为君、重拨紫檀槽。","且和歌一阕，问当前谁最销魂。"]},{"t":"西河 答和王西园送别","f":"古风","c":["春去久，怕逢客馆长昼。","寄君书到正街头，濯枝雨后。","那堪黄浦晚潮生，一帆吹下如溜。","忆当日，方邂逅。","按歌新记红豆。","酒间移烛和予词，霎时草就。","匆匆散去镇蹉跎，蜀葵花发时候。","骊驹唱罢频把袖。","看江流、如许颦皱。","遥指垂杨渡口。","更短亭、东上酒家，依旧欲放歌，何时还又。"]},{"t":"满庭芳","f":"古风","c":["栀子开残，宜男采遍，日长深院啼莺。","正荷衣被暑，裁剪初成。","曾向慈恩寺里，春池浅、蘸笔题名。","人争看，风流拔俗，第一吴兴。","相惊。","旧时八咏东阳，云起处、藻思纵横。","恰衣盘雕锦，纸染红菱。","羡煞丝纶世掌，凤池上、綷羽争明。","悬弧处，堂前花发，海上云生。"]},{"t":"剔银灯 咏米家灯","f":"古风","c":["百尺冰荷可喜。","况满壁、尽张罗绮。","剪縠为栏，堆纱作树，不数米家山水。","隔屏人指。","道人在、隔花屏里。","金粟玉虫累累。","光到处、辘轳齐起。","鸡戴珠竿，龙衔火籥，总是数条红紫。","灯前且醉。","看灯影、照人何几。"]},{"t":"题姚将军五图词","f":"古风","c":["何来采药仙源。","问当年。","云是伏波横海、旧登坛。","麟阁里。","沧洲意。","任相看。","一似桃花流水，向人间。"]},{"t":"十美图词 其一 减字木兰花·灯下收书图","f":"古风","c":["合欢成被。","铺就鹧鸪单枕腻。","豹髓全融。","肯负馋灯入夜红。","壁光如曙。","翻恨袖梢遮不住。","收却残书。","何用掀翻垒算珠。"]},{"t":"十美图词 其二 菩萨蛮·午睡图","f":"古风","c":["玉栏长夏金塘里。","轩窗四面荷风起。","菀蒻织花纹。","盘盘散绿云。","柳帷褰未闭。","隔水窥人至。","待起整钗钿。","郎今未可前。"]},{"t":"十美图词 其三 虞美人·红丝拂子打檀郎图","f":"古风","c":["乐陵台下看红药。","底处曾相谑。","苔衣掩尽石栏花。","辜负东园杏子数枝斜。","紫龙髯拂珊瑚柄。","秃袖红相映。","郎身岂有赭头蝇。","暂作吴宫点墨白螺屏。"]},{"t":"兑阁十词 其一 南歌子·齐世家彤史","f":"古风","c":["朱阀迎齐女，金箱贮楚云。","高阁傍斜曛。","阿谁居阁上，济阳君。"]},{"t":"兑阁十词 其二 鹊桥仙·证前生","f":"古风","c":["蓬山小吏，上清旧籍，曾控九仙朱鲤。","若非花下认前身，几负却、双成久矣。","枫亭何在，治装东去，请食宋家荔子。","纵然置驿未能通，也胜看、忠州画里。"]},{"t":"兑阁十词 其三 小重山·双鱼问","f":"古风","c":["两地烽烟天一隅。","蒋山西尽处、莫愁湖。","谁言流水隔姑苏。","春潮上，中有一双鱼。","缄处印含朱。","泽蒲裁作线、界蜘蛛。","簪花小字画来疏。","凭偷看，传作窦家书。"]},{"t":"兑阁十词 荷叶杯 其四 维摩天女恰同参曾参访耆旧，究向上一层","f":"古风","c":["乃与阿潘同住。","何故。","花月映江潭。","问谁还宿普明龛。","参么参。","参么参。"]},{"t":"兑阁十词 其五 天仙子·病榻闲情","f":"古风","c":["长向花前摊女史。","一榻自安花蔓里。","尽教春去病还留，捐药饵。","弄笔底。","全似建安女博士。","阶下稚童摇葛藟。","满院月明清似水。","慢言蓁莽辟除难，君意气。","且已耳。","泛扫请从一室始。"]},{"t":"兑阁十词 其六 十六字令","f":"古风","c":["齐代远，空吟乘马篇。","真珠钏，解作算商钱。"]},{"t":"兑阁十词 其七 柳梢青·联吟","f":"古风","c":["锦闼闲心，绿窗幽兴，得句相调。","何意东园，杏花开遍，又是春朝。","丁娘且索挥毫。","甚处见、欢情久要。","几阕清词，数行细字，一幅生绡。"]},{"t":"兑阁十词 其八 西河·琴弈双清","f":"古风","c":["且慢记。","琴心当日何似。","只看绿绮绕孤桐，素丝未理。","高山流水有谁听，离怀此际如寄。","况花底，楸树子。","旧枰在断垣里。","空留遗挂紫檀心，琢成累累。","横横直直试踌躇，几曾闲却纤指。","是中意，诚莫己。","良人惜未能此。","追忆尔时佳致。","或庶几、鼓瑟湘灵堪比。","何况围棋张良娣。"]},{"t":"兑阁十词 其九 临江仙·逮下","f":"古风","c":["不辨黄鹂能却妒，临溪且采茵陈。","文园能聘茂陵人。","君心难问取，我见也怜生。","今日秦淮相接处，当年桃树桃根。","门前流水记前因。","曼陀花下影，同拜绣幢身。"]},{"t":"兑阁十词 其十 潇湘逢故人·采菱","f":"古风","c":["采菱歌罢，见紫角新翻，绿苞初卸。","问灌湖前汊。","女伴恁来迟，停船相迓。","红袖风吹，刚一望、夕阳西下。","唤侍儿、慢捲朱竿，菱刺又牵罗帕。","举棹去，南浦夜。","叹洲尽含霜，湾名销夏。","此事思如乍。","待旧约重寻，流光不借。","几度秋风，看浩浩、长淮东泻。","好愁人、翠藻清涟，犹是参差如画。"]},{"t":"乐府补题和词 其一 水龙吟·白莲","f":"古风","c":["前湖十里，芙蓉到门，皦皦明如练。","波光云映，芦埼鹭下，宛然一片。","湘葩含铅，青房滤粉，素珠成串。","便采莲红女，绛裙千褶，遮叶住，有谁见。","只为社中人散。","倚遥空、削成难辨。","赤栏桥子，无端愁把，碧天遮断。","月下飞香，霜前落叶，容华将变。","但秋衣未制，剪来朵朵，不须染茜。"]},{"t":"乐府补题和词 其二 摸鱼儿·莼","f":"古风","c":["但秋风、有谁还忆，夏瓜冬菜春韭。","儿家住近横塘曲，长在柳姑庙后。","相邀取，借邻女花竿、挑起红丝浏。","摘来盈缶。","任九月猪毛，百茎雉尾，总贳一壶酒。","品瀜甚、慢说白如琼玖。","下将盐豉烹就。","钿头钗脚难形似，只顾流匙在口。","还念否。","料拾鲙分鲭、未是和羹手。","踌躇良久。","便羊酪能胜，龙酥堪敌，归去也何有。"]},{"t":"小重山 其三 宫词","f":"古风","c":["水咽铜龙漏断时。","金铺青琐外、蜿双垂。","疏桐玉露滴阶墀。","银床静，缭绕辘轳丝。","袍裤扫鸾帷。","九微花报喜、晚风吹。","额黄催卸却迟迟。","珠帘下，犹望月如眉。"]},{"t":"渔父词 其一","f":"古风","c":["籊籊银钩挂竹竿。","珊瑚车子铁连环。","莲叶渡，蓼花滩。","烟波淼淼几时还。"]},{"t":"渔父词 其二","f":"古风","c":["菰叶菱根罥网丝。","曲榔单板立鸬鹚。","前浦约，隔江期。","江长浦阔暝归迟。"]},{"t":"西溪子 其一","f":"古风","c":["襡襣对裆一抹。","帕复两头八撮。","抱腰身，牵带孔。","持带孔。","卸到烛光浮动。","暖烟浓。","泻轻红。"]},{"t":"西溪子 其二","f":"古风","c":["棋底红编履子。","低?砑罗如水。","夜填时，重解袜。","重束袜。","坐久欲填还脱。","忽见月如钩。","使人愁。"]},{"t":"采莲子 其一","f":"七言绝句","c":["风起莲江绉绿罗。","并船归唱采莲歌。","画屏只见金鸂鶒。","不信双双水鸟多。"]},{"t":"采莲子 其二","f":"七言绝句","c":["细萍点点钉花船。","荇线飘飘缚画竿。","折得小莲羞并蒂。","红靴钩入锦裙边。"]},{"t":"竹枝 其一","f":"七言古诗","c":["十二峰前十二滩。","嘈嘈急水渡来难。"]},{"t":"竹枝 其二","f":"七言古诗","c":["瞿塘看似桃花马，只少装成八宝鞍。"]},{"t":"竹枝 其三","f":"七言古诗","c":["锦江春水白浮浮。","担水娇娘踏水愁。"]},{"t":"竹枝 其四","f":"七言古诗","c":["洗面好来清溜里，洗足当寻浊浪头。"]},{"t":"临江仙 其一","f":"古风","c":["当日虎符初下处，桃花开满山阿。","万层绛帐覆来多。","驱盐投峻阪，拔羽出虞罗。","一自龙山高会后，春江曾哭曹娥。","天南万里到牂柯。","帝乡把盏去，锦里盼车过。"]},{"t":"临江仙 其二","f":"古风","c":["谁料十年星纪换，延津还泛仙槎。","江淮转运使如何。","金笳开越峤，绣棨动吴波。","幸得闲堂仍聚首，清樽频把玻㼈。","刘郎前度喜重过。","公门桃树老，犹有旧枝柯。"]},{"t":"杨将军美人试马请歌","f":"七言古诗","c":["将军航头载美人，春行晚泊横江滨。","斜阳堕地草场阔，酒酣欲试红麒麟。","美人常服双裤褶，青锦鸦襕紫丝结。","蝉鬓当风卷似云，马毛散汗吹如血。","金钱压口玉袜肤，马前细立秦罗敷。","见人羞上还将堕，壮士惊前不敢扶。","调鞍整辔坐不定，忽见桃花满春径。","将军似妒九华鞯，在傍休视双金镫。","明霞片片争绕林。","红光落处桃花深。","回头失却真珠瓅，春草苍茫何处寻？"]},{"t":"钱编修所藏司马相如玉印歌","f":"七言古诗","c":["汉庭司马梁园客，早岁为郎晚驰驿。","因慕邯郸旧相贤，借取高名注属籍。","当时原有摹玺书，大者砻石小琢玗。","螭首龟膊总衔带，碧文绿籀皆施朱。","相传解玉刻小记，四角中央构名字。","檄使填将《喻蜀文》，酒徒印作当垆契。","于今相隔几千年，不虞此物留人间。","土衣苔绣半斑驳，银钩玉筋还新鲜。","截肪径寸覆玦纽，何必黄金大如斗。","钱郎得此真罕希，每与秘书通系肘。","会当天子好古文，相如已是同时人。","尚书给札令缮赋，落笔殿前如有神。","遂登著作入金马，名在何须更相假。","对策姑令董相先，容才久为廉颇下。","长安秋尽寒欲来，驱车一上昭王台。","酒间出示争把玩，令我怀古生徘徊。","前人意气不长在，况复微文等光怪。","何物精灵护此符，历劫千秋不曾坏。","龙门遗册懒未收，图书堆垛能生愁。","我今欲借文园篆，一惹桃花纸上油。"]},{"t":"送人之耒阳","f":"七言律诗","c":["湖北湖南水尽浮，杜鹃啼歇过衡州。","几重高峡穿天下，万里平江入汉流。","念母徐生终去魏，思乡王粲故依刘。","少陵古墓依然在，酹酒荒原无限愁。"]},{"t":"秦淮老人","f":"七言绝句","c":["秦淮高阁拟临春，中有仙翁鬓似银。","话到陪京行乐处，尚疑身是太平人。"]},{"t":"竹枝","f":"七言律诗","c":["十二峰前十二滩。","嘈嘈急水渡来难。","瞿塘看似桃花马，只少装成八宝鞍。","锦江春水白浮浮。","担水娇娘踏水愁。","洗面好来清溜里，洗足当寻浊浪头。"]}]};